insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('bb-puree-dinde-courgette-riz', 'Purée de dinde, courgette et riz', 'Une purée de midi douce, épaissie au riz bien cuit.', array['baby']::text[], array['lunch']::text[], array['m6_8']::text[], 6, 12, array['smooth','mashed']::text[], 1, null, 10, 20, array[]::text[], array['puree','complete','protein']::text[], array['Le poulet remplace la dinde.','Vers 8 mois, écrasez le riz à la fourchette au lieu de le mixer.']::text[], '24 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, bien à cœur, puis laissez tiédir. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Sans sel, sans sucre et sans miel ajoutés avant 1 an.','Volaille toujours cuite à cœur.']::text[], 'Un repas complet : légume, féculent et petite part de volaille.', 1, array['spring','summer']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
