insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('pd-tartine-cacahuete-banane', 'Tartines au beurre de cacahuète et rondelles de banane', 'Une tartine nourrissante, sans sucre ajouté, pour les grosses faims du matin.', array['child','family']::text[], array['breakfast']::text[], array[]::text[], 36, 120, array['regular']::text[], 4, null, 5, 0, array['gluten','peanuts']::text[], array['quick','protein','fiber','budget','vegetarian']::text[], array['Allergie à l’arachide : remplacez par de la purée d’amande ou de sésame si elles sont tolérées, ou par du fromage frais.','Vérifiez l’absence d’allergie avant la première introduction de l’arachide.']::text[], 'À préparer juste avant de manger (la banane noircit).', array['Étalez le beurre de cacahuète en couche très fine : une couche épaisse colle au palais et peut gêner la déglutition.','Arachide : allergène majeur, à proposer seulement si l’enfant la tolère déjà.','Arachide : à proposer seulement si elle a déjà été introduite sans réaction ; une première fois se fait à la maison, en petite quantité, quand on peut surveiller l’enfant. En cas d’allergie connue ou de doute, demandez l’avis du médecin.']::text[], 'Le beurre de cacahuète apporte des protéines et des lipides, la banane des glucides et des fibres.', 1, array[]::text[], 'cold', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
