insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('pd-pancakes-yaourt-myrtilles', 'Pancakes moelleux au yaourt et aux myrtilles', 'Les pancakes du week-end, épais et légers, avec très peu de sucre.', array['child','family']::text[], array['breakfast']::text[], array[]::text[], 24, 120, array['regular']::text[], 5, null, 15, 20, array['gluten','eggs','milk']::text[], array['calcium','freezer','family','vegetarian']::text[], array['Hors saison, framboises ou fruits rouges surgelés (sans les décongeler).','Pour les plus grands, ajoutez un zeste de citron.']::text[], '2 jours au réfrigérateur ; 1 mois au congélateur.', array['Avant 4 ans, myrtilles coupées en deux ou écrasées.']::text[], 'Seulement 1 cuillère de sucre pour 5 portions ; les myrtilles apportent la douceur.', 1, array['summer']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
