insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'pd-pancakes-yaourt-myrtilles' and owner_id is null), 2, 'Ajoutez le yaourt, les œufs et le lait, puis fouettez jusqu’à une pâte lisse et épaisse.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'pd-pancakes-yaourt-myrtilles' and owner_id is null), 3, 'Coupez les myrtilles en deux et incorporez-les délicatement.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'pd-pancakes-yaourt-myrtilles' and owner_id is null), 4, 'Faites fondre un peu de beurre dans une poêle et faites cuire de petites louches de pâte 2 à 3 minutes par face, jusqu’à ce qu’elles soient dorées et cuites à cœur.') on conflict do nothing;
