insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('pd-crepes-orange', 'Crêpes légères parfumées au zeste d’orange', 'Des crêpes fines pour le petit-déjeuner du dimanche, peu sucrées.', array['child','family']::text[], array['breakfast']::text[], array[]::text[], 24, 120, array['regular']::text[], 6, null, 10, 25, array['gluten','eggs','milk']::text[], array['family','freezer','budget','vegetarian']::text[], array['Garniture : compote, fromage blanc, fruits frais plutôt que pâte à tartiner.','Sans lait : boisson végétale au soja.']::text[], '48 h au réfrigérateur, filmées ; 2 mois au congélateur.', array[]::text[], 'Une crêpe fine avec un fruit frais compose un petit-déjeuner simple.', 1, array['winter']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
