insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'pd-crepes-orange' and owner_id is null), 5, 'orange', 'orange', 1, 'u', 'non traitée', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'pd-crepes-orange' and owner_id is null), 6, 'sugar', 'sucre', 1, 'cs', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'pd-crepes-orange' and owner_id is null), 1, 'Dans un saladier, mélangez la farine et le sucre, creusez un puits et cassez-y les œufs.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'pd-crepes-orange' and owner_id is null), 2, 'Versez le lait petit à petit en fouettant pour éviter les grumeaux, puis ajoutez l’huile et le zeste d’orange. Laissez reposer 30 minutes si possible (repos).') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'pd-crepes-orange' and owner_id is null), 3, 'Faites chauffer une poêle légèrement huilée et versez une petite louche de pâte en l’étalant finement.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'pd-crepes-orange' and owner_id is null), 4, 'Faites cuire environ 1 minute par face, jusqu’à ce que la crêpe soit dorée. Recommencez jusqu’à épuisement de la pâte.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'pd-crepes-orange' and owner_id is null), 5, 'Servez avec des quartiers d’orange pressés en jus ou en segments.') on conflict do nothing;
