insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('pd-petit-dej-japonais-riz-omelette', 'Petit-déjeuner à la japonaise : riz, omelette fine et concombre', 'Un plateau salé inspiré du Japon, pour découvrir d’autres façons de commencer la journée.', array['child','family']::text[], array['breakfast']::text[], array[]::text[], 36, 120, array['regular']::text[], 4, null, 15, 15, array['gluten','eggs','soy','sesame']::text[], array['world','protein','vegetables','vegetarian']::text[], array['Allergie au sésame ou au soja : supprimez-les.','Avec un reste de riz de la veille, réchauffé à cœur.']::text[], 'Le riz cuit se garde 24 h au réfrigérateur, refroidi rapidement. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Sauce soja : quelques gouttes seulement, elle est très salée.']::text[], 'Un féculent, un œuf et un légume : un petit-déjeuner salé complet.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
