insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-pilons-poulet-miel-moutarde-four', 'Pilons de poulet miel-moutarde, pommes de terre et carottes au four', 'Un plat du dimanche cuit sur une seule plaque, doux et légèrement caramélisé.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 45, array['mustard']::text[], array['family','protein','vegetables','complete']::text[], array['Sans moutarde : remplacez-la par un peu de jus de citron.','Avec des cuisses entières, comptez 10 minutes de plus.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Vérifiez qu’il ne reste ni os ni cartilage dans l’assiette de l’enfant.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une volaille, des pommes de terre et des carottes réunies dans un même plat.', 1, array[]::text[], 'hot', '{"baby":"Le miel est exclu avant 1 an : prélevez une part de poulet et de légumes cuite sans la sauce, puis écrasez-la.","child":"Viande détachée de l’os et coupée en petits morceaux."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
