insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'vi-pilons-poulet-miel-moutarde-four' and owner_id is null), 2, 'potato', 'pomme de terre', 600, 'g', null, false) on conflict do nothing;
