insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-pilons-poulet-miel-moutarde-four' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Épluchez les pommes de terre et les carottes, coupez-les en quartiers et en tronçons de taille régulière.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-pilons-poulet-miel-moutarde-four' and owner_id is null), 2, 'Mélangez le miel, la moutarde, l’huile d’olive et le thym dans un saladier ; enrobez-en les pilons.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-pilons-poulet-miel-moutarde-four' and owner_id is null), 3, 'Étalez les légumes sur une grande plaque, posez les pilons par-dessus et versez le reste de sauce.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-pilons-poulet-miel-moutarde-four' and owner_id is null), 4, 'Enfournez 45 minutes en retournant les pilons à mi-cuisson : la chair doit se détacher de l’os, le jus doit être clair et il ne doit rester aucune trace rosée près de l’os (74 °C à cœur au thermomètre).') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-pilons-poulet-miel-moutarde-four' and owner_id is null), 5, 'Pour les plus jeunes, retirez la peau et détachez la viande de l’os en petits morceaux.') on conflict do nothing;
