insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-poulet-basquaise-doux-riz', 'Poulet basquaise tout doux et riz blanc', 'La version familiale du poulet aux poivrons, sans piment et longuement mijotée.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 45, array[]::text[], array['family','protein','vegetables','complete','batch','freezer']::text[], array['Pour un enfant qui trie les poivrons, mixez la sauce avant d’y remettre le poulet.','Les adultes peuvent ajouter du piment d’Espelette dans leur assiette.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Un plat complet avec une volaille, des légumes cuits et un féculent.', 2, array['summer','autumn']::text[], 'hot', '{"baby":"Dès 8 mois environ : prélevez avant tout ajout de sel une petite part de viande bien cuite et de légumes, mixez ou écrasez finement selon l’âge.","child":"Poulet coupé en petits morceaux, sauce mixée si besoin."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'vi-poulet-basquaise-doux-riz' and owner_id is null), 1, 'chicken_thigh', 'cuisses de poulet', 600, 'g', 'désossées, sans peau', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'vi-poulet-basquaise-doux-riz' and owner_id is null), 2, 'bell_pepper', 'poivron rouge', 2, 'u', null, false) on conflict do nothing;
