insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'vi-poulet-basquaise-doux-riz' and owner_id is null), 8, 'rice', 'riz', 250, 'g', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-poulet-basquaise-doux-riz' and owner_id is null), 1, 'Coupez le poulet en morceaux de 3 cm. Épluchez l’oignon et l’ail, émincez-les ; lavez les poivrons et taillez-les en lanières fines.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-poulet-basquaise-doux-riz' and owner_id is null), 2, 'Faites dorer le poulet 5 minutes dans l’huile d’olive dans une cocotte, puis réservez-le.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-poulet-basquaise-doux-riz' and owner_id is null), 3, 'Faites revenir l’oignon, l’ail et les poivrons 8 minutes à feu moyen, ajoutez le paprika, les tomates concassées et le poulet.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-poulet-basquaise-doux-riz' and owner_id is null), 4, 'Couvrez et laissez mijoter 30 minutes : les poivrons doivent être fondants et le poulet cuit à cœur, sans rose au centre des morceaux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-poulet-basquaise-doux-riz' and owner_id is null), 5, 'Pendant ce temps, faites cuire le riz dans une grande casserole d’eau, égouttez-le et servez-le avec la sauce.') on conflict do nothing;
