insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-poulet-creme-champignons-tagliatelles', 'Émincé de poulet à la crème et aux champignons, tagliatelles', 'Un plat crémeux et rapide pour un dîner de semaine.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 10, 20, array['gluten','milk']::text[], array['quick','family','protein']::text[], array['Les champignons peuvent être mixés dans la crème pour un enfant qui n’aime pas leur texture.','Sans lactose : remplacez la crème par une crème végétale.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une volaille et un féculent ; ajoutez une salade ou des crudités râpées pour les légumes.', 2, array[]::text[], 'hot', '{"child":"Coupez les tagliatelles et le poulet en petits morceaux pour les plus jeunes."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
