insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-poulet-creme-champignons-tagliatelles' and owner_id is null), 1, 'Taillez le poulet en fines lanières. Nettoyez les champignons et émincez-les ; épluchez et ciselez l’échalote.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-poulet-creme-champignons-tagliatelles' and owner_id is null), 2, 'Faites cuire les pâtes dans une grande casserole d’eau bouillante selon le temps indiqué.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-poulet-creme-champignons-tagliatelles' and owner_id is null), 3, 'Dans une poêle, faites dorer le poulet dans l’huile 6 à 8 minutes en remuant, jusqu’à ce qu’il soit blanc à cœur, sans trace rosée.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-poulet-creme-champignons-tagliatelles' and owner_id is null), 4, 'Ajoutez l’échalote et les champignons, faites sauter 5 minutes, puis versez la crème et laissez frémir 3 minutes.') on conflict do nothing;
