insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-nuggets-poulet-petales-mais-four', 'Nuggets de poulet croustillants aux pétales de maïs, potatoes au four', 'Des nuggets maison panés aux pétales de maïs nature et cuits au four.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 25, 35, array['gluten','eggs']::text[], array['family','picky','protein','freezer','finger']::text[], array['Sans gluten : remplacez la farine par de la fécule de maïs.','Servez avec des crudités râpées et une sauce au yaourt.']::text[], 'Les nuggets crus panés se congèlent à plat 3 mois ; faites-les cuire sans décongeler, 25 minutes, jusqu’à ce qu’ils soient cuits à cœur. Cuits : 48 h au réfrigérateur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une volaille, un féculent ; complétez avec des légumes en accompagnement.', 1, array[]::text[], 'hot', '{"child":"Pour les moins de 4 ans, coupez chaque nugget en deux."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
