insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-nuggets-poulet-petales-mais-four' and owner_id is null), 1, 'Préchauffez le four à 210 °C. Lavez les pommes de terre, coupez-les en quartiers et mélangez-les avec l’huile et le paprika sur une plaque ; enfournez 15 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-nuggets-poulet-petales-mais-four' and owner_id is null), 2, 'Coupez le poulet en morceaux de la taille d’une bouchée. Écrasez grossièrement les pétales de maïs dans un sac.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-nuggets-poulet-petales-mais-four' and owner_id is null), 3, 'Passez chaque morceau dans la farine, puis dans l’œuf battu, puis dans les pétales.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-nuggets-poulet-petales-mais-four' and owner_id is null), 4, 'Disposez les nuggets sur une seconde plaque et enfournez avec les pommes de terre 20 minutes en les retournant : le poulet doit être blanc et cuit à cœur (74 °C), la panure dorée.') on conflict do nothing;
