insert into public.recipe_reviews (recipe_id, status, by_label, note, created_at) select (select id from public.recipes where slug = 'vi-nuggets-poulet-petales-mais-four' and owner_id is null), 'ai_draft', 'Rédaction par une IA (Claude, Anthropic)', 'Import du lot de brouillons ; contrôles automatiques réussis, relecture humaine à faire.', '2026-10-20' where not exists (select 1 from public.recipe_reviews where recipe_id = (select id from public.recipes where slug = 'vi-nuggets-poulet-petales-mais-four' and owner_id is null) and status = 'ai_draft');
insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-brochettes-poulet-yaourt-citron-semoule', 'Brochettes de poulet au yaourt et citron, semoule aux courgettes', 'Une marinade douce qui garde le poulet moelleux, pour les beaux jours.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 30, 20, array['gluten','milk']::text[], array['family','protein','vegetables','complete']::text[], array['Au barbecue, vérifiez la cuisson au centre du plus gros morceau.','Sans produit laitier : marinez avec huile d’olive et citron.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Ne laissez jamais un jeune enfant manger directement sur une pique.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une volaille, une céréale et un légume d’été.', 2, array['spring','summer']::text[], 'hot', '{"baby":"Dès 8 mois environ : prélevez avant tout ajout de sel une petite part de viande bien cuite et de légumes, mixez ou écrasez finement selon l’âge.","child":"Viande retirée des piques et coupée petit."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'vi-brochettes-poulet-yaourt-citron-semoule' and owner_id is null), 1, 'chicken', 'blanc de poulet', 500, 'g', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'vi-brochettes-poulet-yaourt-citron-semoule' and owner_id is null), 2, 'yogurt', 'yaourt nature', 125, 'g', null, false) on conflict do nothing;
