insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'vi-brochettes-poulet-yaourt-citron-semoule' and owner_id is null), 8, 'mint', 'menthe fraîche', 1, 'cs', 'ciselée', true) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-brochettes-poulet-yaourt-citron-semoule' and owner_id is null), 1, 'Coupez le poulet en cubes de 2 à 3 cm. Mélangez-les avec le yaourt, le jus du citron et le cumin ; laissez reposer 20 minutes au réfrigérateur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-brochettes-poulet-yaourt-citron-semoule' and owner_id is null), 2, 'Enfilez les cubes sur des piques et faites-les cuire au four sous le gril ou à la plancha 12 à 15 minutes en les retournant : le poulet doit être blanc à cœur, sans rose, jus clair.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-brochettes-poulet-yaourt-citron-semoule' and owner_id is null), 3, 'Pendant ce temps, lavez les courgettes, coupez-les en petits dés et faites-les sauter 8 minutes dans une cuillerée d’huile d’olive.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-brochettes-poulet-yaourt-citron-semoule' and owner_id is null), 4, 'Versez sur la semoule le même volume d’eau bouillante, couvrez 5 minutes, puis égrainez-la avec le reste d’huile et les courgettes ; ajoutez la menthe si vous le souhaitez.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-brochettes-poulet-yaourt-citron-semoule' and owner_id is null), 5, 'Retirez les morceaux de poulet des piques avant de servir les enfants.') on conflict do nothing;
