insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-poulet-coco-patate-douce-epinards', 'Mijoté de poulet au lait de coco, patate douce et épinards', 'Un plat doux et parfumé au curcuma, sans piment.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 35, array[]::text[], array['family','protein','vegetables','complete','batch','freezer','world']::text[], array['Riz blanc possible pour un enfant qui préfère.','Les adultes peuvent relever leur assiette avec un peu de pâte de curry.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une volaille, un légume orange et un légume vert, avec un féculent complet.', 2, array['autumn','winter']::text[], 'hot', '{"baby":"Dès 8 mois environ : prélevez avant tout ajout de sel une petite part de viande bien cuite et de légumes, mixez ou écrasez finement selon l’âge.","child":"Servez tel quel, poulet en petits dés."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
