insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-poulet-coco-patate-douce-epinards' and owner_id is null), 1, 'Mettez le riz complet à cuire dans une grande casserole d’eau, environ 30 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-poulet-coco-patate-douce-epinards' and owner_id is null), 2, 'Coupez le poulet en dés. Épluchez l’oignon et émincez-le ; épluchez les patates douces et taillez-les en cubes de 2 cm.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-poulet-coco-patate-douce-epinards' and owner_id is null), 3, 'Dans une sauteuse, faites revenir l’oignon dans l’huile 3 minutes, ajoutez le poulet, le gingembre et le curcuma et faites dorer 5 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-poulet-coco-patate-douce-epinards' and owner_id is null), 4, 'Ajoutez les patates douces, le lait de coco et 150 ml d’eau ; couvrez et laissez mijoter 20 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-poulet-coco-patate-douce-epinards' and owner_id is null), 5, 'Ajoutez les épinards encore surgelés et poursuivez 5 minutes : la patate douce doit être fondante et le poulet cuit à cœur, sans rose.') on conflict do nothing;
