insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-gratin-pates-poulet-brocoli-bechamel', 'Gratin de coquillettes au poulet et brocoli, béchamel maison', 'Un gratin complet qui se prépare la veille et se réchauffe au four.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 35, array['gluten','milk']::text[], array['family','protein','calcium','vegetables','complete','make_ahead']::text[], array['Avec un reste de poulet rôti : ajoutez-le directement, en petits morceaux.','Brocoli surgelé possible, sans le décongeler.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Un plat complet avec volaille, féculent, légume vert et produit laitier.', 1, array['autumn','winter','spring']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
