insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-gratin-pates-poulet-brocoli-bechamel' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Faites cuire les coquillettes 2 minutes de moins que le temps indiqué ; ajoutez les fleurettes de brocoli dans la même eau les 5 dernières minutes, puis égouttez.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-gratin-pates-poulet-brocoli-bechamel' and owner_id is null), 2, 'Coupez le poulet en petits dés et faites-le cuire 7 minutes à la poêle, jusqu’à ce qu’il soit blanc à cœur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-gratin-pates-poulet-brocoli-bechamel' and owner_id is null), 3, 'Béchamel : faites fondre le beurre, ajoutez la farine, puis versez le lait petit à petit en fouettant ; laissez épaissir 5 minutes et ajoutez la muscade.') on conflict do nothing;
