insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-boulettes-poulet-courgette-polenta', 'Boulettes de poulet à la courgette, sauce tomate et polenta crémeuse', 'Des boulettes tendres où la courgette passe inaperçue.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 25, 30, array['gluten','eggs']::text[], array['family','protein','vegetables','batch','freezer','picky','complete']::text[], array['Sans œuf : 2 cuillerées de fromage blanc lient aussi la farce.','Polenta remplaçable par des pâtes ou du riz.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas. Écrasez les boulettes à la fourchette pour les plus jeunes.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une volaille, un légume caché dans la farce, une sauce tomate et un féculent.', 1, array[]::text[], 'hot', '{"baby":"Dès 9 mois environ : une boulette bien cuite écrasée dans la sauce, avec un peu de polenta, sans sel ajouté.","child":"Boulettes coupées en deux ou en quatre avant 4 ans."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
