insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'vi-boulettes-poulet-courgette-polenta' and owner_id is null), 9, 'olive_oil', 'huile d''olive', 1, 'cs', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-boulettes-poulet-courgette-polenta' and owner_id is null), 1, 'Râpez finement la courgette et pressez-la dans un torchon pour retirer l’eau. Mélangez-la avec le poulet haché, la chapelure, l’œuf et le persil.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-boulettes-poulet-courgette-polenta' and owner_id is null), 2, 'Façonnez une vingtaine de petites boulettes avec les mains mouillées.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-boulettes-poulet-courgette-polenta' and owner_id is null), 3, 'Faites revenir l’oignon émincé dans l’huile d’olive, ajoutez les tomates concassées et laissez frémir 5 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-boulettes-poulet-courgette-polenta' and owner_id is null), 4, 'Déposez les boulettes dans la sauce, couvrez et laissez cuire 20 minutes à petit feu en les retournant : coupez-en une, l’intérieur doit être blanc, sans rose (74 °C).') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-boulettes-poulet-courgette-polenta' and owner_id is null), 5, 'Versez la polenta en pluie dans 800 ml d’eau frémissante et remuez 5 minutes jusqu’à ce qu’elle soit crémeuse. Servez avec les boulettes.') on conflict do nothing;
