insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-cuisses-poulet-fenouil-orange-four', 'Cuisses de poulet au four, fenouil et orange', 'Un plat parfumé et doux, cuit sur la plaque avec ses pommes de terre.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 50, array[]::text[], array['family','protein','vegetables','complete']::text[], array['Le fenouil cuit est fondant et peu anisé ; vous pouvez le remplacer par des carottes.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Vérifiez qu’il ne reste ni os ni cartilage.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une volaille, des légumes et un féculent dans le même plat.', 2, array['winter','spring']::text[], 'hot', '{"baby":"Dès 8 mois environ : prélevez avant tout ajout de sel une petite part de viande bien cuite et de légumes, mixez ou écrasez finement selon l’âge.","child":"Viande désossée, coupée petit."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
