insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-cuisses-poulet-fenouil-orange-four' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Coupez le fenouil en fins quartiers et les pommes de terre en rondelles épaisses.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-cuisses-poulet-fenouil-orange-four' and owner_id is null), 2, 'Disposez-les dans un grand plat avec l’huile d’olive et le thym, posez les cuisses de poulet par-dessus.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-cuisses-poulet-fenouil-orange-four' and owner_id is null), 3, 'Arrosez avec le jus de l’orange et ajoutez le zeste râpé.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-cuisses-poulet-fenouil-orange-four' and owner_id is null), 4, 'Enfournez 50 minutes en arrosant deux fois : la chair doit se détacher de l’os, le jus doit être clair et sans trace rosée près de l’os (74 °C à cœur).') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-cuisses-poulet-fenouil-orange-four' and owner_id is null), 5, 'Retirez peau et os pour les enfants et coupez la viande en petits morceaux.') on conflict do nothing;
