insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-riz-poulet-petits-pois-carottes-cocotte', 'Riz au poulet, petits pois et carottes en cocotte', 'Un plat unique où tout cuit ensemble, pratique les soirs pressés.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 27, array[]::text[], array['quick','budget','family','complete','protein','batch']::text[], array['Remplacez les petits pois par des haricots verts coupés ou du maïs.','Une cuillerée de crème rend le plat plus fondant.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur. Le riz cuit se refroidit vite et se garde au froid. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Riz cuit : refroidissez-le rapidement et ne le laissez pas à température ambiante.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Un plat complet avec volaille, féculent et deux légumes.', 1, array[]::text[], 'hot', '{"baby":"Dès 8 mois environ : prélevez avant tout ajout de sel une petite part de viande bien cuite et de légumes, mixez ou écrasez finement selon l’âge.","child":"Servez tel quel."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
