insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'vi-riz-poulet-petits-pois-carottes-cocotte' and owner_id is null), 7, 'olive_oil', 'huile d''olive', 1, 'cs', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-riz-poulet-petits-pois-carottes-cocotte' and owner_id is null), 1, 'Coupez le poulet en dés, épluchez les carottes et taillez-les en petits dés, émincez l’oignon.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-riz-poulet-petits-pois-carottes-cocotte' and owner_id is null), 2, 'Dans une cocotte, faites revenir l’oignon et le poulet dans l’huile d’olive 5 minutes, jusqu’à ce que le poulet soit blanc à l’extérieur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-riz-poulet-petits-pois-carottes-cocotte' and owner_id is null), 3, 'Ajoutez le riz et le curcuma, remuez 1 minute, puis versez 600 ml d’eau chaude et les carottes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-riz-poulet-petits-pois-carottes-cocotte' and owner_id is null), 4, 'Couvrez et laissez cuire 15 minutes à feu doux, ajoutez les petits pois et poursuivez 5 minutes : le riz doit avoir absorbé l’eau et le poulet être cuit à cœur.') on conflict do nothing;
