insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-poulet-saute-brocoli-sauce-sesame-riz', 'Poulet sauté au brocoli, sauce sésame et riz', 'Une poêlée rapide nappée d’une sauce douce au tahini.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 20, array['gluten','soy','sesame']::text[], array['quick','family','protein','vegetables','complete','world']::text[], array['Allergie au sésame : remplacez le tahini par du fromage blanc ou de la crème.','Sauce soja réduite en sel : une seule cuillerée suffit pour 4.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une volaille, un légume vert et un féculent.', 2, array[]::text[], 'hot', '{"child":"Brocoli et poulet en petits morceaux ; sauce à part si l’enfant préfère."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
