insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-croquettes-poulet-patate-douce', 'Croquettes de poulet et patate douce à la ciboulette', 'Des galettes tendres à préparer en grande quantité et à congeler.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 30, 47, array['gluten','eggs']::text[], array['family','batch','freezer','finger','picky','protein']::text[], array['Avec un reste de poulet rôti, sautez l’étape du pochage.','Remplacez la patate douce par de la pomme de terre ou de la courge.']::text[], 'Cuites et refroidies : 48 h au réfrigérateur, 3 mois au congélateur. Réchauffez au four 15 minutes, jusqu’à ce qu’elles soient bien chaudes à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.','Avant 4 ans : feuilles de salade ciselées finement.']::text[], 'Une volaille et un légume orange réunis dans une croquette.', 2, array['autumn','winter']::text[], 'hot', '{"baby":"Dès 9 mois environ : une croquette émiettée et écrasée, sans sel ajouté.","child":"À manger avec les doigts."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
