insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-pitas-poulet-sauce-yaourt-concombre', 'Pitas garnies au poulet grillé et sauce yaourt-concombre', 'Un repas à garnir soi-même, frais et rassasiant.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 12, array['gluten','milk']::text[], array['quick','family','protein','vegetables','world']::text[], array['Pour les plus jeunes, coupez la pita garnie en quatre petits triangles.','Sans lactose : sauce au yaourt végétal.']::text[], 'Poulet cuit : 48 h au réfrigérateur ; sauce : 24 h. Assemblez au moment du repas.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une volaille, des légumes crus et un produit laitier dans un pain.', 2, array['spring','summer']::text[], 'hot', '{"child":"Concombre râpé dans la sauce, salade ciselée finement."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
