insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-poulet-tomate-olives-polenta-grillee', 'Cuisses de poulet mijotées à la tomate et aux olives, polenta', 'Un mijoté provençal doux, servi avec une polenta onctueuse.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 45, array[]::text[], array['family','protein','batch','freezer']::text[], array['Olives facultatives pour un enfant qui ne les aime pas : servez-les à part.','Ajoutez une courgette en dés pour davantage de légumes.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Olives : toujours dénoyautées et coupées en quatre avant 4 ans.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une volaille et un féculent dans une sauce aux tomates ; complétez avec une salade.', 2, array['summer','autumn']::text[], 'hot', '{"child":"Olives coupées en quatre, poulet en petits morceaux."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
