insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-poulet-tomate-olives-polenta-grillee' and owner_id is null), 1, 'Coupez le poulet en gros morceaux et faites-le dorer 5 minutes dans l’huile d’olive dans une cocotte.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-poulet-tomate-olives-polenta-grillee' and owner_id is null), 2, 'Ajoutez l’oignon et l’ail émincés, faites revenir 3 minutes, puis les tomates concassées et les herbes de Provence.') on conflict do nothing;
