insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-papillotes-poulet-courgette-tomates-cerises' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Coupez les courgettes en fines rondelles et les tomates cerises en quatre.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-papillotes-poulet-courgette-tomates-cerises' and owner_id is null), 2, 'Sur quatre grands carrés de papier cuisson, répartissez les courgettes, posez un blanc de poulet, ajoutez les tomates, une rondelle de citron, le basilic et l’huile d’olive. Fermez hermétiquement.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-papillotes-poulet-courgette-tomates-cerises' and owner_id is null), 3, 'Enfournez 25 minutes. Ouvrez une papillote et coupez le blanc au centre : il doit être blanc, sans rose, jus clair (74 °C).') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-papillotes-poulet-courgette-tomates-cerises' and owner_id is null), 4, 'Pendant ce temps, faites cuire le riz dans une grande casserole d’eau et égouttez-le. Servez avec le jus des papillotes.') on conflict do nothing;
