insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-escalopes-dinde-panees-parmesan-haricots-verts', 'Escalopes de dinde panées au parmesan, haricots verts et purée', 'Une panure dorée au four, sans friture.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 25, array['gluten','eggs','milk']::text[], array['family','protein','vegetables','complete','picky']::text[], array['Escalopes panées crues : se congèlent à plat ; cuisez-les sans décongeler 25 minutes.','Sans gluten : chapelure de pétales de maïs nature.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une volaille, un légume vert, un féculent et du lait dans la purée.', 2, array[]::text[], 'hot', '{"child":"Escalope coupée en petites lanières."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
