insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-boulettes-dinde-ricotta-epinards-four', 'Boulettes de dinde à la ricotta et aux épinards, sauce tomate au four', 'Des boulettes très moelleuses grâce à la ricotta, cuites dans leur sauce.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 25, 30, array['gluten','eggs','milk']::text[], array['family','protein','batch','freezer','calcium']::text[], array['Ricotta remplaçable par du fromage frais.','Doublez les quantités et congelez une fournée de boulettes cuites dans leur sauce.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas. Coupez les boulettes en quatre pour les plus jeunes.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une volaille, un légume vert dans la farce, une sauce tomate et un féculent.', 2, array[]::text[], 'hot', '{"baby":"Dès 9 mois environ : une boulette bien cuite écrasée dans un peu de sauce, sans sel ajouté.","child":"Boulettes coupées en quatre avant 4 ans."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
