insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-dinde-pomme-curry-doux-riz', 'Émincé de dinde à la pomme et au curry doux, riz basmati', 'Un plat sucré-salé tout en douceur, la pomme fond dans la sauce.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 25, array['milk','celery','mustard']::text[], array['quick','family','protein','picky','world']::text[], array['Lait de coco possible à la place de la crème.','Curry doux uniquement ; les adultes peuvent ajouter du piment à part.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une volaille, un fruit cuit et un féculent ; complétez avec un légume vert.', 2, array['autumn','winter']::text[], 'hot', '{"child":"Dinde coupée en petits morceaux."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
