insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-dinde-pomme-curry-doux-riz' and owner_id is null), 2, 'Coupez la dinde en lanières, épluchez les pommes et coupez-les en petits dés, émincez l’oignon.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-dinde-pomme-curry-doux-riz' and owner_id is null), 3, 'Faites revenir l’oignon dans l’huile 3 minutes, ajoutez la dinde et faites-la dorer 6 minutes.') on conflict do nothing;
