insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-lasagnes-dinde-courgettes', 'Lasagnes à la dinde et aux courgettes', 'Des lasagnes plus légères en viande, riches en légumes, idéales pour le congélateur.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 30, 68, array['gluten','eggs','milk']::text[], array['family','batch','freezer','protein','vegetables','calcium','complete','make_ahead']::text[], array['Feuilles sans œuf : vérifiez l’étiquette pour un enfant allergique.','Ajoutez des épinards entre deux couches.']::text[], 'Cuites : 48 h au réfrigérateur, 3 mois au congélateur en parts. Réchauffez 30 minutes au four à 180 °C, jusqu’à ce que ce soit bien chaud à cœur.', array['Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Un plat complet avec volaille, légumes, féculent et produit laitier.', 2, array[]::text[], 'hot', '{"baby":"Dès 10 mois environ : une petite part écrasée à la fourchette.","child":"Servez tel quel, coupé en petits carrés."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
