insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'vi-lasagnes-dinde-courgettes' and owner_id is null), 9, 'emmental', 'emmental en bloc (râpé à la maison)', 80, 'g', 'râpé', false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-lasagnes-dinde-courgettes' and owner_id is null), 1, 'Faites revenir l’oignon émincé et la dinde hachée 8 minutes en émiettant, jusqu’à ce que la viande ne soit plus rose du tout. Ajoutez les courgettes en petits dés et les tomates concassées, laissez mijoter 15 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-lasagnes-dinde-courgettes' and owner_id is null), 2, 'Béchamel : faites fondre le beurre, ajoutez la farine, puis le lait en fouettant ; laissez épaissir 5 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-lasagnes-dinde-courgettes' and owner_id is null), 3, 'Préchauffez le four à 180 °C. Dans un plat, alternez sauce à la dinde, feuilles de lasagnes et béchamel, en terminant par la béchamel.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-lasagnes-dinde-courgettes' and owner_id is null), 4, 'Parsemez d’emmental et enfournez 40 minutes : les feuilles doivent être tendres sous la pointe d’un couteau.') on conflict do nothing;
