insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'vi-brochettes-dinde-ananas-poivron-riz' and owner_id is null), 2, 'pineapple', 'ananas', 250, 'g', 'frais ou au naturel', false) on conflict do nothing;
