insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'vi-brochettes-dinde-ananas-poivron-riz' and owner_id is null), 7, 'rice', 'riz', 250, 'g', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-brochettes-dinde-ananas-poivron-riz' and owner_id is null), 1, 'Coupez la dinde, l’ananas et le poivron en cubes de 2 cm. Mélangez la sauce soja, le miel et l’huile, et enrobez-en les cubes de dinde ; laissez reposer 15 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-brochettes-dinde-ananas-poivron-riz' and owner_id is null), 2, 'Enfilez en alternance dinde, ananas et poivron sur des piques.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-brochettes-dinde-ananas-poivron-riz' and owner_id is null), 3, 'Faites cuire 12 à 15 minutes sous le gril du four ou à la plancha en retournant : la dinde doit être blanche à cœur, sans rose.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-brochettes-dinde-ananas-poivron-riz' and owner_id is null), 4, 'Servez avec le riz cuit à l’eau, après avoir retiré les morceaux des piques pour les enfants.') on conflict do nothing;
