insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-hachis-dinde-potiron', 'Hachis de dinde et purée de potiron gratinée', 'Un hachis d’automne tout orange, léger et réconfortant.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 25, 50, array['milk']::text[], array['family','batch','freezer','protein','vegetables','picky']::text[], array['Potiron remplaçable par de la butternut ou du potimarron (inutile de l’éplucher).']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une volaille, un légume orange et un féculent avec un produit laitier.', 1, array['autumn','winter']::text[], 'hot', '{"baby":"Dès 9 mois environ : une part de purée avec un peu de dinde bien cuite, écrasée, sans fromage ni sel.","child":"Servez tel quel."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
