insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-hachis-dinde-potiron' and owner_id is null), 1, 'Épluchez le potiron et les pommes de terre, coupez-les en cubes et faites-les cuire 20 minutes à la vapeur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-hachis-dinde-potiron' and owner_id is null), 2, 'Faites revenir l’oignon émincé, ajoutez la dinde hachée et faites-la cuire 8 minutes en l’émiettant, jusqu’à ce qu’elle ne soit plus rose du tout.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-hachis-dinde-potiron' and owner_id is null), 3, 'Écrasez les légumes avec le lait chaud, le beurre et la muscade.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-hachis-dinde-potiron' and owner_id is null), 4, 'Préchauffez le four à 200 °C. Étalez la viande dans un plat, couvrez de purée, parsemez d’emmental et faites gratiner 20 minutes.') on conflict do nothing;
