insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-couscous-dinde-legumes-abricots', 'Couscous doux à la dinde, aux légumes et aux abricots secs', 'Un couscous familial parfumé au ras-el-hanout, sans piment.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 25, 40, array['gluten']::text[], array['family','protein','vegetables','fiber','complete','world','batch']::text[], array['Sans abricots secs : quelques dés de pomme dans le bouillon.','Les adultes peuvent ajouter de la harissa dans leur assiette.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur. Le bouillon et la viande se congèlent 3 mois.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Abricots secs coupés en tout petits morceaux avant 4 ans ; pois chiches écrasés pour les plus jeunes.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une volaille, une légumineuse, des légumes et une céréale dans un même repas.', 2, array['autumn','winter','spring']::text[], 'hot', '{"child":"Pois chiches écrasés et abricots coupés très petits avant 4 ans."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
