insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'vi-couscous-dinde-legumes-abricots' and owner_id is null), 9, 'olive_oil', 'huile d''olive', 2, 'cs', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-couscous-dinde-legumes-abricots' and owner_id is null), 1, 'Coupez la dinde en cubes. Épluchez les carottes et coupez-les en tronçons, les courgettes en gros dés. Coupez les abricots secs en petits morceaux (avant 4 ans, très petits).') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-couscous-dinde-legumes-abricots' and owner_id is null), 2, 'Dans une cocotte, faites dorer la dinde et l’oignon émincé dans une cuillerée d’huile d’olive 5 minutes, avec le ras-el-hanout.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-couscous-dinde-legumes-abricots' and owner_id is null), 3, 'Ajoutez les carottes et 600 ml d’eau, laissez cuire 15 minutes ; ajoutez les courgettes, les pois chiches rincés et les abricots, poursuivez 15 minutes, jusqu’à ce que la dinde soit cuite à cœur et les légumes tendres.') on conflict do nothing;
