insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-boeuf-carottes-mijote-pommes-de-terre', 'Bœuf-carottes mijoté et pommes de terre fondantes', 'Le grand classique familial, cuit doucement jusqu’à ce que la viande se coupe à la fourchette.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 165, array[]::text[], array['family','iron','protein','vegetables','complete','batch','freezer','budget']::text[], array['Encore meilleur réchauffé le lendemain.','À l’autocuiseur : 45 minutes après la mise en pression.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas. Effilochez la viande pour les plus jeunes.','Retirez la feuille de laurier.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande rouge, des légumes et un féculent mijotés ensemble.', 2, array['autumn','winter']::text[], 'hot', '{"baby":"Dès 8 mois environ : un peu de viande effilochée mixée avec carottes et pommes de terre, sans sel ajouté.","child":"Viande effilochée et légumes coupés en petits morceaux."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
