insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-boeuf-carottes-mijote-pommes-de-terre' and owner_id is null), 1, 'Faites dorer les cubes de bœuf dans l’huile d’olive dans une cocotte, en plusieurs fois, 8 minutes au total.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-boeuf-carottes-mijote-pommes-de-terre' and owner_id is null), 2, 'Ajoutez les oignons émincés et l’ail, faites revenir 3 minutes, puis les carottes épluchées coupées en rondelles, le thym et le laurier.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-boeuf-carottes-mijote-pommes-de-terre' and owner_id is null), 3, 'Couvrez d’eau à hauteur, portez à frémissement, couvrez et laissez mijoter à feu très doux 120 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-boeuf-carottes-mijote-pommes-de-terre' and owner_id is null), 4, 'Ajoutez les pommes de terre épluchées en gros cubes et poursuivez 30 minutes : la viande doit être cuite à cœur et si tendre qu’elle s’effiloche.') on conflict do nothing;
