insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-chili-con-carne-doux-riz', 'Chili con carne tout doux à la carotte, riz blanc', 'Une version familiale sans piment, épaissie aux haricots rouges.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 40, array[]::text[], array['family','iron','fiber','protein','complete','batch','freezer','world']::text[], array['Moitié bœuf, moitié lentilles : une version plus économique.','Les adultes ajoutent piment ou sauce piquante dans leur assiette.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Avant 4 ans : écrasez légèrement les haricots rouges à la fourchette.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande rouge, une légumineuse, des légumes et un féculent.', 1, array['autumn','winter']::text[], 'hot', '{"child":"Haricots écrasés pour les plus jeunes ; une cuillerée de yaourt adoucit encore."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
