insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-chili-con-carne-doux-riz' and owner_id is null), 1, 'Faites revenir l’oignon en petits dés et la carotte râpée finement dans l’huile 5 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-chili-con-carne-doux-riz' and owner_id is null), 2, 'Ajoutez le bœuf haché et faites-le cuire 8 minutes en l’émiettant, jusqu’à ce qu’il soit bien cuit à cœur, sans aucune trace rosée (70 °C au thermomètre).') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-chili-con-carne-doux-riz' and owner_id is null), 3, 'Ajoutez le cumin, le cacao (il arrondit la sauce sans la sucrer), les tomates concassées et les haricots rouges rincés ; laissez mijoter 25 minutes à couvert.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-chili-con-carne-doux-riz' and owner_id is null), 4, 'Pendant ce temps, faites cuire le riz dans une grande casserole d’eau et égouttez-le. Servez ensemble.') on conflict do nothing;
