insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-parmentier-boeuf-celeri-carottes-comte', 'Parmentier de bœuf aux carottes, purée pomme de terre-céleri au comté', 'Un hachis enrichi en légumes, à préparer en double pour le congélateur.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 25, 55, array['milk','celery']::text[], array['family','iron','protein','vegetables','batch','freezer','complete','calcium']::text[], array['Céleri remplaçable par du panais ou du potiron.','Allergie au céleri : remplacez-le par des pommes de terre.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande rouge, deux légumes et un féculent avec un fromage à pâte pressée cuite.', 2, array['autumn','winter']::text[], 'hot', '{"baby":"Dès 9 mois environ : purée et viande bien cuite écrasées ensemble, avant d’ajouter le fromage.","child":"Servez tel quel."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
