insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-parmentier-boeuf-celeri-carottes-comte' and owner_id is null), 1, 'Épluchez les pommes de terre et le céleri, coupez-les en cubes et faites-les cuire 25 minutes à l’eau ; écrasez-les avec le lait chaud, le beurre et la muscade.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-parmentier-boeuf-celeri-carottes-comte' and owner_id is null), 2, 'Faites revenir l’oignon émincé et les carottes râpées 5 minutes, ajoutez le bœuf haché et faites-le cuire 8 minutes en l’émiettant, jusqu’à ce qu’il soit bien cuit à cœur, sans aucune trace rosée (70 °C au thermomètre).') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-parmentier-boeuf-celeri-carottes-comte' and owner_id is null), 3, 'Préchauffez le four à 200 °C. Étalez la viande dans un plat, couvrez de purée et parsemez de comté.') on conflict do nothing;
