insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-bolognaise-boeuf-legumes-caches', 'Bolognaise de bœuf aux légumes cachés, pâtes complètes', 'Une sauce riche en légumes mixés, à congeler en portions.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 45, array['gluten','milk']::text[], array['family','iron','protein','vegetables','batch','freezer','picky','fiber']::text[], array['Mixez la sauce pour un enfant qui repère les légumes.','Pâtes blanches possibles si l’enfant préfère.']::text[], 'Sauce : 48 h au réfrigérateur, 3 mois au congélateur en portions. Réchauffez une seule fois, jusqu’à ce qu’elle soit bien chaude.', array['Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande rouge, beaucoup de légumes et un féculent complet.', 1, array[]::text[], 'hot', '{"baby":"Dès 9 mois environ : un peu de sauce bien cuite mixée avec des petites pâtes, sans parmesan ni sel ajouté.","child":"Pâtes coupées pour les plus jeunes."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
