insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-bolognaise-boeuf-legumes-caches' and owner_id is null), 1, 'Râpez finement les carottes et la courgette ; hachez l’oignon et l’ail.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-bolognaise-boeuf-legumes-caches' and owner_id is null), 2, 'Faites revenir les légumes dans l’huile d’olive 5 minutes, ajoutez le bœuf haché et faites-le cuire 8 minutes en l’émiettant, jusqu’à ce qu’il soit bien cuit à cœur, sans aucune trace rosée (70 °C au thermomètre).') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-bolognaise-boeuf-legumes-caches' and owner_id is null), 3, 'Ajoutez les tomates concassées, le concentré de tomate et les herbes de Provence ; laissez mijoter 30 minutes à couvert, en remuant de temps en temps.') on conflict do nothing;
