insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-keftas-boeuf-boulgour-sauce-yaourt', 'Keftas de bœuf au cumin, boulgour et sauce yaourt-citron', 'Des boulettes allongées parfumées, servies avec une sauce fraîche.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 25, 20, array['gluten','eggs','milk']::text[], array['family','iron','protein','world','freezer']::text[], array['Avec de l’agneau haché, la recette fonctionne aussi.','Boulgour remplaçable par de la semoule.']::text[], 'Keftas crues : 3 mois au congélateur, cuites sans décongeler 20 minutes. Cuites : 48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas. Coupez les keftas dans la longueur en quatre, puis en petits morceaux (jamais en rondelles), ou émiettez-les.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande rouge, une céréale, une crudité et un produit laitier.', 2, array['spring','summer','autumn']::text[], 'hot', '{"child":"Keftas coupées dans la longueur en quatre, puis en petits morceaux, sauce à part."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
