insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-keftas-boeuf-boulgour-sauce-yaourt' and owner_id is null), 1, 'Râpez l’oignon et mélangez-le avec le bœuf haché, le cumin, la coriandre et l’œuf. Façonnez 16 petites saucisses.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-keftas-boeuf-boulgour-sauce-yaourt' and owner_id is null), 2, 'Faites cuire le boulgour 12 minutes dans deux fois son volume d’eau.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-keftas-boeuf-boulgour-sauce-yaourt' and owner_id is null), 3, 'Faites cuire les keftas 12 à 15 minutes dans une poêle antiadhésive ou au four à 200 °C en les retournant : elles doivent être bien cuit à cœur, sans aucune trace rosée (70 °C au thermomètre).') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-keftas-boeuf-boulgour-sauce-yaourt' and owner_id is null), 4, 'Mélangez le yaourt avec le jus du citron. Coupez les tomates en petits dés et servez le tout ensemble.') on conflict do nothing;
