insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-steaks-haches-maison-frites-patate-douce', 'Steaks hachés maison bien cuits et frites de patate douce au four', 'Le repas « burger » sans pain, avec des frites cuites au four.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 30, array['eggs']::text[], array['family','iron','protein','picky','freezer']::text[], array['Avec des petits pains, à faire en burgers pour les plus grands.','Patate douce remplaçable par des pommes de terre.']::text[], 'Steaks crus façonnés : 3 mois au congélateur, entre deux feuilles de papier. Cuits : 48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Steak haché : jamais rosé pour un enfant, quel que soit son âge.','Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande rouge, un légume féculent et une salade.', 2, array[]::text[], 'hot', '{"child":"Steak coupé en petits morceaux, salade ciselée finement."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
