insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'vi-steaks-haches-maison-frites-patate-douce' and owner_id is null), 8, 'lettuce', 'salade verte', 1, 'u', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-steaks-haches-maison-frites-patate-douce' and owner_id is null), 1, 'Préchauffez le four à 210 °C. Coupez les patates douces en bâtonnets, mélangez-les avec l’huile d’olive et le paprika et étalez-les sur une plaque ; enfournez 30 minutes en les retournant.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-steaks-haches-maison-frites-patate-douce' and owner_id is null), 2, 'Mélangez le bœuf haché avec l’oignon râpé, le persil et l’œuf ; formez 4 à 6 steaks peu épais.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-steaks-haches-maison-frites-patate-douce' and owner_id is null), 3, 'Faites-les cuire 5 à 6 minutes de chaque côté dans une poêle chaude : pour les enfants, le steak haché doit être bien cuit à cœur, sans aucune trace rosée (70 °C au thermomètre).') on conflict do nothing;
