insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-daube-douce-boeuf-orange-pates', 'Daube douce de bœuf à l’orange et à la tomate, pâtes', 'Un mijoté provençal adouci par l’orange, parfait pour le batch cooking du week-end.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 165, array['gluten']::text[], array['family','iron','protein','batch','freezer','make_ahead']::text[], array['Polenta ou pommes de terre à la place des pâtes.','Préparez la veille : le goût est meilleur et le gras se retire facilement une fois froid.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas. Effilochez la viande.','Retirez le laurier.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande rouge mijotée avec des légumes et un féculent.', 2, array['autumn','winter']::text[], 'hot', '{"baby":"Dès 8 mois environ : viande effilochée et carottes mixées, sans sel ajouté.","child":"Viande effilochée."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
