insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-daube-douce-boeuf-orange-pates' and owner_id is null), 1, 'Faites dorer les cubes de bœuf dans l’huile d’olive dans une cocotte 8 minutes, en plusieurs fois.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-daube-douce-boeuf-orange-pates' and owner_id is null), 2, 'Ajoutez l’oignon et l’ail émincés, les carottes en rondelles, les tomates concassées, le zeste et le jus de l’orange, le thym et le laurier.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-daube-douce-boeuf-orange-pates' and owner_id is null), 3, 'Ajoutez 300 ml d’eau, couvrez et laissez mijoter à feu très doux 150 minutes : la viande doit être cuite à cœur et fondante.') on conflict do nothing;
