insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-moussaka-douce-boeuf-aubergine', 'Moussaka douce au bœuf, aubergines et pommes de terre', 'Un gratin grec familial, avec une pointe de cannelle.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 30, 75, array['gluten','milk']::text[], array['family','iron','protein','vegetables','batch','freezer','calcium','world']::text[], array['Avec de l’agneau haché pour une version plus traditionnelle.','Courgettes possibles à la place d’une partie des aubergines.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Un plat complet avec viande rouge, légumes, féculent et produit laitier.', 2, array['summer','autumn']::text[], 'hot', '{"child":"Coupé en petits carrés."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
