insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'vi-moussaka-douce-boeuf-aubergine' and owner_id is null), 11, 'olive_oil', 'huile d''olive', 2, 'cs', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-moussaka-douce-boeuf-aubergine' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Coupez les aubergines et les pommes de terre en rondelles de 5 mm, badigeonnez-les d’huile d’olive et faites-les rôtir 20 minutes sur des plaques.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-moussaka-douce-boeuf-aubergine' and owner_id is null), 2, 'Faites revenir l’oignon émincé, ajoutez le bœuf haché et faites-le cuire 8 minutes en l’émiettant, jusqu’à ce qu’il soit bien cuit à cœur, sans aucune trace rosée (70 °C au thermomètre). Ajoutez les tomates concassées et la cannelle, laissez mijoter 10 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-moussaka-douce-boeuf-aubergine' and owner_id is null), 3, 'Béchamel : faites fondre le beurre, ajoutez la farine, puis le lait en fouettant ; laissez épaissir 5 minutes et ajoutez le parmesan.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-moussaka-douce-boeuf-aubergine' and owner_id is null), 4, 'Dans un plat, alternez pommes de terre, aubergines et viande, nappez de béchamel et faites gratiner 30 minutes à 180 °C.') on conflict do nothing;
