insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-pot-au-feu-familial-legumes', 'Pot-au-feu familial aux légumes d’hiver', 'Un bouillon, une viande fondante et ses légumes : un repas complet qui se réchauffe bien.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 25, 185, array[]::text[], array['family','iron','protein','vegetables','complete','batch','freezer','budget']::text[], array['Le bouillon dégraissé sert de base à une soupe aux vermicelles le lendemain.','Moutarde et cornichons uniquement pour les adultes.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur. Le bouillon se congèle seul dans des bocaux.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas. Effilochez la viande.','Bouillon brûlant : laissez-le tiédir avant de servir l’enfant.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande rouge et quatre légumes, avec un féculent.', 2, array['winter']::text[], 'hot', '{"baby":"Dès 8 mois environ : prélevez légumes et viande avant d’ajouter le sel, mixez-les avec un peu de bouillon.","child":"Viande effilochée et légumes écrasés à la fourchette pour les plus jeunes."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
