insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'vi-pot-au-feu-familial-legumes' and owner_id is null), 9, 'salt', 'sel', 1, 'pincee', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-pot-au-feu-familial-legumes' and owner_id is null), 1, 'Mettez le bœuf dans un grand faitout, couvrez d’eau froide et portez à frémissement ; écumez pendant 10 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-pot-au-feu-familial-legumes' and owner_id is null), 2, 'Ajoutez l’oignon entier, le laurier, le thym et une pincée de sel ; laissez frémir à couvert 120 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-pot-au-feu-familial-legumes' and owner_id is null), 3, 'Ajoutez les carottes, les poireaux et les navets épluchés et coupés en gros morceaux ; poursuivez 30 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-pot-au-feu-familial-legumes' and owner_id is null), 4, 'Ajoutez les pommes de terre et cuisez encore 25 minutes : la viande doit être cuite à cœur, très tendre, et les légumes fondants.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-pot-au-feu-familial-legumes' and owner_id is null), 5, 'Servez le bouillon en entrée, puis la viande et les légumes.') on conflict do nothing;
