insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-nouilles-riz-boeuf-hache-brocoli', 'Nouilles de riz sautées au bœuf haché, brocoli et carottes', 'Une poêlée express qui change des pâtes.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 15, array['gluten','soy']::text[], array['quick','family','iron','protein','vegetables','world']::text[], array['Sans gluten : vérifiez l’étiquette de la sauce soja ou prenez un tamari.','Ajoutez des petits pois ou du maïs.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : nouilles coupées courtes et légumes bien tendres.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande rouge, deux légumes et un féculent.', 2, array[]::text[], 'hot', '{"child":"Nouilles coupées aux ciseaux."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
