insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-nouilles-riz-boeuf-hache-brocoli' and owner_id is null), 1, 'Faites tremper ou cuire les nouilles de riz selon le paquet, puis rincez-les et coupez-les aux ciseaux pour les enfants.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-nouilles-riz-boeuf-hache-brocoli' and owner_id is null), 2, 'Coupez le brocoli en petites fleurettes et les carottes en fins bâtonnets ; faites-les cuire 5 minutes à la vapeur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-nouilles-riz-boeuf-hache-brocoli' and owner_id is null), 3, 'Dans une grande poêle, faites revenir l’ail et le gingembre dans l’huile 1 minute, ajoutez le bœuf haché et faites-le cuire 7 minutes en l’émiettant, jusqu’à ce qu’il soit bien cuit à cœur, sans aucune trace rosée (70 °C au thermomètre).') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-nouilles-riz-boeuf-hache-brocoli' and owner_id is null), 4, 'Ajoutez les légumes, les nouilles et la sauce soja, faites sauter 3 minutes en mélangeant.') on conflict do nothing;
