insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-tortillas-boeuf-mais-avocat', 'Tortillas garnies au bœuf, maïs, avocat et emmental', 'Un repas à garnir soi-même qui fait toujours plaisir.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 36, 120, array['regular']::text[], 4, null, 20, 10, array['gluten','milk']::text[], array['quick','family','iron','protein','vegetables','picky','world']::text[], array['Végétarien : remplacez le bœuf par des haricots rouges écrasés.','Pour les plus jeunes, roulez la tortilla serrée et coupez-la en tronçons.']::text[], 'Viande cuite : 48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur. L’avocat écrasé se prépare au moment.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Avant 4 ans : écrasez le maïs.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande rouge, des légumes, un féculent et du fromage.', 2, array['spring','summer']::text[], 'hot', '{"child":"Tortilla roulée et coupée en tronçons."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
