insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-gratin-gnocchis-boeuf-tomate-mozzarella' and owner_id is null), 3, 'Mélangez les gnocchis crus avec la sauce dans un plat et couvrez de mozzarella coupée en dés.') on conflict do nothing;
