insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-pain-viande-boeuf-carottes-haricots-verts', 'Pain de viande au bœuf et aux carottes, haricots verts', 'Un « meatloaf » moelleux à trancher, aussi bon chaud que froid.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 65, array['gluten','eggs']::text[], array['family','iron','protein','vegetables','batch','freezer','lunchbox','complete']::text[], array['Froid en tranches, il se glisse dans une boîte à repas avec une salade.','Moitié bœuf, moitié dinde pour un goût plus doux.']::text[], 'Cuit : 72 h au réfrigérateur ; tranches congelées 3 mois, à réchauffer jusqu’à ce qu’elles soient bien chaudes à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande rouge, des légumes et des féculents.', 1, array[]::text[], 'hot', '{"baby":"Dès 9 mois environ : une tranche écrasée avec des haricots verts mixés, sans sel ajouté.","child":"Tranche coupée en petits cubes."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
