insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-pain-viande-boeuf-carottes-haricots-verts' and owner_id is null), 2, 'Mélangez le bœuf haché, les légumes râpés, les flocons d’avoine, les œufs, le persil et la moitié du concentré de tomate.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-pain-viande-boeuf-carottes-haricots-verts' and owner_id is null), 3, 'Tassez dans un moule à cake, badigeonnez le dessus du reste de concentré et enfournez 55 minutes : piquez le centre, le jus doit être clair et la viande bien cuit à cœur, sans aucune trace rosée (70 °C au thermomètre).') on conflict do nothing;
