insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-minestrone-boeuf-petites-pates', 'Minestrone au bœuf et aux petites pâtes', 'Une soupe-repas épaisse, avec viande, légumes et pâtes dans le même bol.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 90, array['gluten','milk']::text[], array['family','iron','protein','vegetables','complete','batch','freezer','budget']::text[], array['Haricots blancs possibles en plus pour une version plus copieuse.','Sans viande : ajoutez des haricots blancs et des lentilles.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur. Congelez sans les pâtes, ajoutées au réchauffage.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Soupe brûlante : laissez tiédir.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande rouge, des légumes et un féculent dans une soupe complète.', 1, array['autumn','winter','spring']::text[], 'hot', '{"child":"Viande en tout petits dés ; écrasez si besoin."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
