insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-minestrone-boeuf-petites-pates' and owner_id is null), 1, 'Coupez le bœuf en tout petits dés de 1 cm. Faites-la dorer avec l’oignon émincé dans l’huile d’olive 5 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-minestrone-boeuf-petites-pates' and owner_id is null), 2, 'Ajoutez les tomates concassées, les herbes et 1,2 litre d’eau ; laissez frémir 60 minutes à couvert.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-minestrone-boeuf-petites-pates' and owner_id is null), 3, 'Ajoutez les carottes en dés et les haricots verts coupés en tronçons, cuisez 15 minutes, puis la courgette en dés et les petites pâtes, encore 10 minutes : la viande doit être cuite à cœur et tendre.') on conflict do nothing;
