insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-blanquette-veau-riz', 'Blanquette de veau à l’ancienne et riz', 'La blanquette familiale, douce et crémeuse, cuite à petit feu.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 25, 95, array['gluten','milk']::text[], array['family','protein','batch','freezer','complete']::text[], array['Avec de l’épaule de dinde, plus économique.','Sans crème : la sauce reste onctueuse avec un jaune d’œuf ajouté hors du feu puis réchauffée jusqu’à frémissement.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Retirez la feuille de laurier.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande, des légumes et un féculent avec une sauce au beurre et à la crème.', 3, array['autumn','winter']::text[], 'hot', '{"baby":"Dès 8 mois environ : un peu de veau et de carottes mixés avec du bouillon, sans la sauce.","child":"Viande coupée en petits morceaux."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
