insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-blanquette-veau-riz' and owner_id is null), 1, 'Mettez le veau dans une cocotte, couvrez d’eau froide, portez à frémissement et écumez 5 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-blanquette-veau-riz' and owner_id is null), 2, 'Ajoutez l’oignon, les carottes en rondelles et le laurier ; laissez mijoter à couvert 75 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-blanquette-veau-riz' and owner_id is null), 3, 'Faites revenir les champignons émincés 5 minutes dans une noisette de beurre. Faites cuire le riz à l’eau.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-blanquette-veau-riz' and owner_id is null), 4, 'Faites fondre le reste du beurre, ajoutez la farine, puis 500 ml du bouillon de cuisson en fouettant ; laissez épaissir 5 minutes, ajoutez la crème et le jus de citron.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-blanquette-veau-riz' and owner_id is null), 5, 'Remettez la viande, cuite à cœur et tendre, les carottes et les champignons dans la sauce ; servez avec le riz, sans le laurier.') on conflict do nothing;
