insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-saute-veau-petits-legumes-printemps', 'Sauté de veau aux petits pois, carottes nouvelles et pommes de terre', 'Un plat printanier qui mijote doucement en cocotte.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 95, array[]::text[], array['family','protein','vegetables','complete','batch']::text[], array['Avec de l’épaule d’agneau, c’est un navarin.','Ajoutez des fèves ou des asperges en saison.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas. Écrasez les petits pois pour les plus jeunes.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande, deux légumes et un féculent.', 3, array['spring']::text[], 'hot', '{"baby":"Dès 8 mois environ : prélevez avant tout ajout de sel une petite part de viande bien cuite et de légumes, mixez ou écrasez finement selon l’âge.","child":"Viande en petits morceaux."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
