insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-tajine-agneau-abricots-secs-semoule', 'Tajine d’agneau aux abricots secs, carottes et semoule', 'Un tajine sucré-salé doux, cuit longuement jusqu’à ce que la viande fonde.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 100, array['gluten']::text[], array['family','iron','protein','world','batch','freezer']::text[], array['Ajoutez des pois chiches pour un plat plus copieux.','Avec du poulet, comptez 40 minutes de cuisson.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Abricots secs coupés en tout petits morceaux avant 4 ans.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande rouge, des légumes, un fruit sec et une céréale.', 3, array['autumn','winter']::text[], 'hot', '{"child":"Viande effilochée, abricots coupés très petits."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
