insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-navarin-agneau-printanier', 'Navarin d’agneau printanier aux navets et petits pois', 'Un ragoût de printemps aux légumes nouveaux.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 25, 95, array['gluten']::text[], array['family','iron','protein','vegetables','complete','batch','freezer']::text[], array['Dégraissez la sauce à froid si vous la préparez la veille.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas. Écrasez les petits pois pour les plus jeunes.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande rouge, trois légumes et un féculent.', 3, array['spring']::text[], 'hot', '{"baby":"Dès 8 mois environ : prélevez avant tout ajout de sel une petite part de viande bien cuite et de légumes, mixez ou écrasez finement selon l’âge.","child":"Viande en petits morceaux, légumes écrasés si besoin."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
