insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-boulettes-agneau-menthe-courgettes-semoule', 'Boulettes d’agneau à la menthe, courgettes rôties et sauce yaourt', 'Des boulettes parfumées, cuites au four avec leurs légumes.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 25, 20, array['gluten','milk']::text[], array['family','iron','protein','vegetables','freezer','world']::text[], array['Avec du bœuf haché si l’agneau n’est pas apprécié.','Sauce yaourt servie à part.']::text[], 'Boulettes crues : 3 mois au congélateur. Cuites : 48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas. Coupez les boulettes en quatre.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande rouge, un légume, une céréale et un produit laitier.', 3, array['spring','summer']::text[], 'hot', '{"child":"Boulettes coupées en quatre avant 4 ans."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
