insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-boulettes-agneau-menthe-courgettes-semoule' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Mélangez l’agneau haché, l’oignon râpé, la moitié de la menthe, la chapelure et le cumin ; formez 20 boulettes.') on conflict do nothing;
