insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-agneau-mijote-haricots-blancs', 'Épaule d’agneau mijotée aux haricots blancs et à la tomate', 'Un plat de partage longuement mijoté, inspiré de l’agneau aux flageolets.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 115, array[]::text[], array['family','iron','protein','fiber','batch','freezer','complete']::text[], array['Au four en cocotte fermée à 160 °C, pour le même temps.','Flageolets possibles à la place des haricots blancs.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas. Écrasez légèrement les haricots pour les plus jeunes.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande rouge et une légumineuse avec des légumes.', 3, array['autumn','winter']::text[], 'hot', '{"baby":"Dès 9 mois environ : agneau effiloché et haricots mixés avec la sauce, sans sel ajouté.","child":"Viande effilochée, haricots écrasés si besoin."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
