insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-filet-mignon-porc-pommes-four', 'Filet mignon de porc rôti aux pommes et pommes de terre', 'Un rôti tendre, des pommes fondantes et des pommes de terre dorées dans le même plat.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 50, array[]::text[], array['family','protein','complete']::text[], array['Poires à la place des pommes en automne.','Ajoutez des carottes pour davantage de légumes.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande, un fruit cuit et un féculent ; complétez avec un légume vert.', 3, array['autumn','winter']::text[], 'hot', '{"baby":"Dès 8 mois environ : prélevez avant tout ajout de sel une petite part de viande bien cuite et de légumes, mixez ou écrasez finement selon l’âge.","child":"Tranches fines coupées en petits morceaux."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
