insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-filet-mignon-porc-pommes-four' and owner_id is null), 1, 'Préchauffez le four à 190 °C. Coupez les pommes de terre en quartiers et l’oignon en lamelles ; mélangez-les avec l’huile d’olive et le thym dans un plat et enfournez 15 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-filet-mignon-porc-pommes-four' and owner_id is null), 2, 'Faites dorer le filet mignon de porc sur toutes ses faces 5 minutes dans une poêle.') on conflict do nothing;
