insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-filet-mignon-porc-pommes-four' and owner_id is null), 4, 'Vérifiez la cuisson : la viande doit être cuit à cœur, sans rosé, jus clair (70 °C au thermomètre). Laissez reposer 5 minutes avant de trancher.') on conflict do nothing;
