insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-brochettes-porc-paprika-poivrons-riz', 'Brochettes de porc au paprika, poivrons et oignon rouge, riz', 'Des brochettes colorées pour le barbecue ou le gril du four.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 36, 120, array['regular']::text[], 4, null, 30, 20, array[]::text[], array['family','protein','vegetables','complete']::text[], array['Avec du poulet, même temps de cuisson.','Les légumes rôtis peuvent être mixés en sauce pour un enfant qui les trie.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Ne laissez jamais un jeune enfant manger directement sur une pique.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande, trois légumes et un féculent.', 2, array['summer']::text[], 'hot', '{"child":"Viande et légumes retirés des piques et coupés petit."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
