insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-porc-lentilles-vertes-carottes', 'Porc mijoté aux lentilles vertes et carottes', 'Une version familiale du petit salé, plus douce et moins salée.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 40, array[]::text[], array['family','iron','fiber','protein','batch','freezer','budget','complete']::text[], array['Lentilles corail pour une texture plus fondante.','Sans porc : poulet ou dinde, même cuisson.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Avant 4 ans : coupez la viande en petits morceaux tendres, faites asseoir l’enfant et restez près de lui pendant le repas.','Retirez la feuille de laurier.','Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une viande, une légumineuse et des légumes.', 2, array['autumn','winter']::text[], 'hot', '{"baby":"Dès 8 mois environ : lentilles et carottes mixées avec un peu de porc bien cuit, sans sel.","child":"Servez tel quel."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
