insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-risotto-jambon-champignons', 'Risotto crémeux au jambon et aux champignons', 'Un risotto familial sans vin, crémeux grâce au parmesan.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 10, 25, array['milk']::text[], array['quick','family','calcium']::text[], array['Petits pois possibles en plus des champignons.','Le jambon et le parmesan sont salés : n’ajoutez pas de sel.']::text[], '48 h au réfrigérateur dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur. Le riz cuit se refroidit vite et se garde au froid. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Riz cuit : refroidissez-le rapidement, ne le laissez pas à température ambiante.']::text[], 'Un féculent, une charcuterie, un légume et un fromage.', 2, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
