insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-cordons-bleus-maison-dinde-puree-carottes' and owner_id is null), 3, 'Préchauffez le four à 200 °C, posez-les sur une plaque huilée avec l’huile d’olive et enfournez 25 minutes en les retournant : la dinde doit être blanche à cœur, sans rose (74 °C).') on conflict do nothing;
