insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vi-parmentier-poulet-poireaux', 'Parmentier de poulet aux poireaux fondants', 'Une façon douce d’utiliser un reste de poulet rôti.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 55, array['milk']::text[], array['family','protein','vegetables','batch','freezer','budget']::text[], array['Reste de dinde possible.','Ajoutez des carottes râpées dans les poireaux.']::text[], '48 h au réfrigérateur ; jusqu’à 3 mois au congélateur en portions. Décongelez au réfrigérateur la veille et réchauffez une seule fois, jusqu’à ce que ce soit bien chaud à cœur.', array['Manipulez la viande crue à part : lavez planche, couteau et mains avant de toucher les autres aliments.']::text[], 'Une volaille, un légume et un féculent avec un produit laitier.', 1, array['autumn','winter']::text[], 'hot', '{"baby":"Dès 9 mois environ : purée et poireaux bien cuits mixés avec un peu de poulet, sans fromage.","child":"Servez tel quel."}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
