insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-parmentier-poulet-poireaux' and owner_id is null), 1, 'Faites cuire les pommes de terre épluchées 20 minutes à l’eau, écrasez-les avec le lait chaud, la moitié du beurre et la muscade.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-parmentier-poulet-poireaux' and owner_id is null), 2, 'Si le poulet est cru, faites-le pocher 12 minutes dans l’eau frémissante, jusqu’à ce qu’il soit blanc à cœur ; effilochez-le.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-parmentier-poulet-poireaux' and owner_id is null), 3, 'Émincez finement les poireaux et faites-les fondre 15 minutes dans le reste du beurre ; ajoutez la crème et le poulet.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vi-parmentier-poulet-poireaux' and owner_id is null), 4, 'Préchauffez le four à 200 °C. Étalez la fondue de poireaux au poulet dans un plat, couvrez de purée, parsemez d’emmental et faites gratiner 20 minutes.') on conflict do nothing;
