insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-papillote-cabillaud-courgettes-citron', 'Papillotes de cabillaud aux courgettes et au citron, riz blanc', 'Le poisson cuit à la vapeur dans son petit paquet, que chaque enfant ouvre lui-même.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 25, array['fish']::text[], array['protein','vegetables','family','quick']::text[], array['Le cabillaud peut être remplacé par du lieu, du colin ou du merlu.','Laissez l’enfant presser lui-même un quartier de citron sur son assiette.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud au centre. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Poisson : passez les doigts sur toute la chair, avant et après cuisson, et retirez la moindre arête.']::text[], 'Le poisson apporte des protéines, le riz un féculent et les courgettes des légumes.', 2, array['spring','summer']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
