insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-papillote-cabillaud-courgettes-citron' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Faites cuire le riz dans une grande casserole d’eau selon le temps indiqué sur le paquet.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-papillote-cabillaud-courgettes-citron' and owner_id is null), 2, 'Lavez les courgettes et taillez-les en fines rondelles. Coupez le citron en rondelles fines.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-papillote-cabillaud-courgettes-citron' and owner_id is null), 3, 'Posez chaque filet de cabillaud sur une feuille de papier cuisson, après avoir vérifié du bout des doigts qu’il ne reste aucune arête. Ajoutez les courgettes, une rondelle de citron, un filet d’huile d’olive et un peu de thym.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-papillote-cabillaud-courgettes-citron' and owner_id is null), 4, 'Fermez les papillotes hermétiquement et enfournez 18 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-papillote-cabillaud-courgettes-citron' and owner_id is null), 5, 'Ouvrez une papillote pour contrôler la cuisson : la chair doit être opaque jusqu’au centre et s’effeuiller facilement à la fourchette. Sinon, prolongez de 3 à 5 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-papillote-cabillaud-courgettes-citron' and owner_id is null), 6, 'Retirez la rondelle de citron avant de servir avec le riz et émiettez le poisson pour les plus jeunes.') on conflict do nothing;
