insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-papillote-saumon-poireaux-creme', 'Papillotes de saumon aux poireaux fondants et pommes de terre vapeur', 'Des poireaux doux et crémeux qui enveloppent un pavé de saumon.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 25, array['fish','milk']::text[], array['protein','vegetables','family']::text[], array['Allergie au lait : remplacez la crème et le beurre par une cuillerée d’huile d’olive.','Pour les petits, écrasez les pommes de terre avec la crème des poireaux.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud au centre.', array['Poisson : passez les doigts sur toute la chair, avant et après cuisson, et retirez la moindre arête.']::text[], 'Le saumon est un poisson gras ; avec un poisson blanc dans la semaine, on varie les apports.', 3, array['autumn','winter','spring']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
