insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-papillote-saumon-poireaux-creme' and owner_id is null), 1, 'Épluchez les pommes de terre, coupez-les en morceaux et faites-les cuire 20 minutes à la vapeur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-papillote-saumon-poireaux-creme' and owner_id is null), 2, 'Lavez soigneusement les poireaux, émincez-les finement et faites-les fondre 8 minutes dans le beurre, à feu doux, puis ajoutez la crème.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-papillote-saumon-poireaux-creme' and owner_id is null), 3, 'Préchauffez le four à 200 °C. Vérifiez du bout des doigts que les pavés de saumon ne contiennent aucune arête.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-papillote-saumon-poireaux-creme' and owner_id is null), 4, 'Répartissez les poireaux sur quatre feuilles de papier cuisson, posez le saumon dessus et fermez les papillotes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-papillote-saumon-poireaux-creme' and owner_id is null), 5, 'Enfournez 15 à 18 minutes : la chair doit être opaque jusqu’au centre et s’effeuiller facilement à la fourchette. Parsemez de ciboulette et servez avec les pommes de terre.') on conflict do nothing;
