insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-papillote-merlu-tomates-olives-semoule' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Lavez les tomates et coupez-les en dés ; coupez les olives en quatre (indispensable avant 4 ans).') on conflict do nothing;
