insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-papillote-merlu-tomates-olives-semoule' and owner_id is null), 5, 'Pendant ce temps, versez la semoule dans un saladier, couvrez-la du même volume d’eau bouillante, laissez gonfler 5 minutes puis égrainez à la fourchette avec un filet d’huile.') on conflict do nothing;
