insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-gratin-cabillaud-brocoli-bechamel', 'Gratin de cabillaud et brocoli, béchamel à la muscade', 'Un gratin tout doux qui fait aimer le brocoli.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 30, array['gluten','fish','milk']::text[], array['protein','calcium','vegetables','family','picky']::text[], array['Sans gluten : liez la béchamel à la fécule de maïs.','Avec du riz ou des pâtes pour un plat plus copieux.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud au centre.', array['Poisson : passez les doigts sur toute la chair, avant et après cuisson, et retirez la moindre arête.','Avant 5 ans : fromages au lait pasteurisé ou pâtes pressées cuites uniquement.']::text[], 'Le lait et le fromage apportent du calcium, le poisson des protéines.', 2, array['autumn','winter','spring']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
