insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'po-gratin-cabillaud-brocoli-bechamel' and owner_id is null), 7, 'emmental', 'emmental en bloc (râpé à la maison)', 50, 'g', 'râpé', false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-gratin-cabillaud-brocoli-bechamel' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Détaillez le brocoli en petits bouquets et faites-les cuire 6 minutes à l’eau bouillante ; égouttez.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-gratin-cabillaud-brocoli-bechamel' and owner_id is null), 2, 'Préparez la béchamel : faites fondre le beurre, ajoutez la farine, mélangez 1 minute, puis versez le lait petit à petit en fouettant jusqu’à épaississement. Ajoutez la muscade.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-gratin-cabillaud-brocoli-bechamel' and owner_id is null), 3, 'Coupez le cabillaud en gros cubes en vérifiant du bout des doigts qu’il ne reste aucune arête.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-gratin-cabillaud-brocoli-bechamel' and owner_id is null), 4, 'Disposez le poisson et le brocoli dans un plat, nappez de béchamel et parsemez d’emmental.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-gratin-cabillaud-brocoli-bechamel' and owner_id is null), 5, 'Enfournez 20 minutes, jusqu’à ce que le dessus soit doré et que le cabillaud soit cuit à cœur (chair opaque qui s’effeuille).') on conflict do nothing;
