insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-gratin-coquillettes-thon-epinards', 'Gratin de coquillettes au thon et aux épinards', 'Un plat du placard et du congélateur, prêt en une demi-heure.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 10, 25, array['gluten','fish','milk']::text[], array['budget','quick','family','vegetables','batch']::text[], array['Sans lait : remplacez la crème par une sauce tomate et omettez le fromage.','Les pâtes complètes conviennent aussi.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud au centre.', array['Poisson en conserve : vérifiez du bout des doigts qu’il ne reste aucune arête dure (retirez l’arête centrale des sardines).','Avant 5 ans : fromages au lait pasteurisé ou pâtes pressées cuites uniquement.']::text[], 'Un féculent, des légumes verts et du poisson réunis dans un même plat.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
