insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-gratin-coquillettes-thon-epinards' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Faites cuire les pâtes selon le temps indiqué sur le paquet, en les gardant un peu fermes ; égouttez.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-gratin-coquillettes-thon-epinards' and owner_id is null), 2, 'Faites cuire les épinards surgelés 8 minutes à feu moyen avec l’ail écrasé, jusqu’à ce que l’eau s’évapore.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-gratin-coquillettes-thon-epinards' and owner_id is null), 3, 'Émiettez le thon en vérifiant qu’il ne reste aucune arête dure, puis mélangez-le avec les pâtes, les épinards et la crème.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-gratin-coquillettes-thon-epinards' and owner_id is null), 4, 'Versez dans un plat, parsemez d’emmental et faites gratiner 15 minutes, jusqu’à ce que ce soit bien chaud et doré.') on conflict do nothing;
