insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-parmentier-poisson-carottes', 'Parmentier de poisson blanc aux carottes', 'Une couche de poisson et de carottes, une couche de purée maison.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 25, 40, array['fish','milk']::text[], array['protein','family','picky','batch','freezer']::text[], array['Le poisson peut être remplacé par du merlu ou du lieu.','Avec des épinards à la place des carottes pour changer de couleur.']::text[], 'Réfrigérateur : 24 h. Se congèle cru ou cuit (si le poisson n’avait jamais été congelé) pour 2 mois ; réchauffez jusqu’au centre.', array['Poisson : passez les doigts sur toute la chair, avant et après cuisson, et retirez la moindre arête.','Avant 5 ans : fromages au lait pasteurisé ou pâtes pressées cuites uniquement.']::text[], 'Un plat complet : poisson, légumes et féculent.', 2, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
