insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'po-parmentier-poisson-carottes' and owner_id is null), 7, 'emmental', 'emmental en bloc (râpé à la maison)', 40, 'g', 'râpé', false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-parmentier-poisson-carottes' and owner_id is null), 1, 'Épluchez les pommes de terre et les carottes. Faites cuire les pommes de terre 20 minutes à l’eau, et les carottes en rondelles dans la même casserole.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-parmentier-poisson-carottes' and owner_id is null), 2, 'Pendant ce temps, faites pocher le cabillaud 8 minutes dans de l’eau frémissante : la chair doit être opaque jusqu’au centre et s’effeuiller facilement à la fourchette. Égouttez.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-parmentier-poisson-carottes' and owner_id is null), 3, 'Émiettez le poisson avec les doigts en retirant soigneusement toutes les arêtes. Écrasez les carottes à la fourchette et mélangez-les au poisson et au persil.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-parmentier-poisson-carottes' and owner_id is null), 4, 'Écrasez les pommes de terre avec le lait chaud et le beurre pour obtenir une purée.') on conflict do nothing;
