insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-brandade-douce-cabillaud' and owner_id is null), 2, 'Faites chauffer le lait avec l’ail pelé, plongez-y le cabillaud et laissez pocher 8 minutes à petits frémissements : la chair doit être opaque jusqu’au centre et s’effeuiller facilement à la fourchette.') on conflict do nothing;
