insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-galettes-saumon-quinoa-ciboulette' and owner_id is null), 1, 'Faites cuire le quinoa rincé 15 minutes dans deux fois son volume d’eau ; laissez tiédir.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-galettes-saumon-quinoa-ciboulette' and owner_id is null), 2, 'Faites cuire le saumon 10 minutes à la vapeur : la chair doit être opaque jusqu’au centre et s’effeuiller facilement à la fourchette. Émiettez-le en retirant la peau et toutes les arêtes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-galettes-saumon-quinoa-ciboulette' and owner_id is null), 3, 'Mélangez le quinoa, le saumon, les œufs battus, la farine et la ciboulette. Formez 12 petites galettes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-galettes-saumon-quinoa-ciboulette' and owner_id is null), 4, 'Faites-les cuire à la poêle dans l’huile d’olive, 4 minutes par face à feu moyen, jusqu’à ce qu’elles soient dorées et fermes au centre.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-galettes-saumon-quinoa-ciboulette' and owner_id is null), 5, 'Servez avec le concombre coupé en dés et le yaourt en sauce.') on conflict do nothing;
