insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-poisson-pane-petales-mais-haricots-verts', 'Poisson pané aux pétales de maïs et haricots verts', 'Une panure croustillante sans friture, aux pétales de maïs écrasés.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 20, array['gluten','eggs','fish']::text[], array['picky','finger','protein','vegetables','quick']::text[], array['Sans gluten : utilisez de la fécule de maïs à la place de la farine de blé.','Avec des frites de pommes de terre au four pour un repas de fête.']::text[], 'À manger aussitôt pour garder le croustillant ; 24 h au réfrigérateur.', array['Poisson : passez les doigts sur toute la chair, avant et après cuisson, et retirez la moindre arête.']::text[], 'Le poisson apporte des protéines ; les haricots verts complètent l’assiette.', 2, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
