insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-poisson-pane-petales-mais-haricots-verts' and owner_id is null), 1, 'Préchauffez le four à 210 °C. Écrasez les pétales de maïs dans un sac avec un rouleau à pâtisserie et mélangez avec le paprika.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-poisson-pane-petales-mais-haricots-verts' and owner_id is null), 2, 'Coupez le cabillaud en bâtonnets en vérifiant du bout des doigts qu’il ne reste aucune arête.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-poisson-pane-petales-mais-haricots-verts' and owner_id is null), 3, 'Passez chaque bâtonnet dans la farine, puis dans l’œuf battu, puis dans les pétales de maïs.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-poisson-pane-petales-mais-haricots-verts' and owner_id is null), 4, 'Posez sur une plaque huilée, arrosez d’un filet d’huile et enfournez 15 minutes, jusqu’à ce que la panure soit dorée et la chair doit être opaque jusqu’au centre et s’effeuiller facilement à la fourchette.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-poisson-pane-petales-mais-haricots-verts' and owner_id is null), 5, 'Pendant ce temps, faites cuire les haricots verts 12 minutes à la vapeur. Servez avec des quartiers de citron.') on conflict do nothing;
