insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-batonnets-merlu-panure-sesame-petits-pois', 'Bâtonnets de merlu en panure au sésame, petits pois', 'Une panure au sésame qui change de la chapelure seule.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 20, array['gluten','eggs','fish','milk','sesame']::text[], array['finger','picky','protein','vegetables']::text[], array['Allergie au sésame : supprimez les graines et doublez la chapelure.','Le merlu peut être remplacé par du colin ou du lieu.']::text[], 'À manger aussitôt ; 24 h au réfrigérateur.', array['Poisson : passez les doigts sur toute la chair, avant et après cuisson, et retirez la moindre arête.']::text[], 'Le poisson et les petits pois apportent des protéines ; les petits pois aussi des fibres.', 2, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
