insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-nuggets-poisson-polenta-parmesan', 'Nuggets de poisson en croûte de polenta et parmesan', 'Une panure dorée, sans gluten, pour des filets de poisson surgelés.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 25, array['eggs','fish','milk']::text[], array['finger','picky','protein','family']::text[], array['Sans lait : remplacez le parmesan par un peu plus de polenta.','Avant 4 ans : vérifiez que les carottes sont bien tendres sous la dent.']::text[], 'À manger aussitôt ; 24 h au réfrigérateur, réchauffez au four.', array['Poisson : passez les doigts sur toute la chair, avant et après cuisson, et retirez la moindre arête.','Avant 5 ans : fromages au lait pasteurisé ou pâtes pressées cuites uniquement.']::text[], 'Le poisson apporte des protéines ; les carottes rôties, des légumes.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
