insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-nuggets-poisson-polenta-parmesan' and owner_id is null), 5, 'Enfournez 20 minutes en retournant à mi-cuisson : les carottes doivent être tendres et le poisson cuit à cœur, opaque et qui s’effeuille.') on conflict do nothing;
