insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-boulettes-sardines-sauce-tomate-semoule', 'Boulettes de sardines à la sauce tomate et semoule', 'Les sardines en boîte deviennent de tendres boulettes en sauce.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 30, array['gluten','eggs','fish','milk']::text[], array['budget','protein','world','family','freezer']::text[], array['Avant 4 ans : coupez les boulettes en deux ou en quatre.','Sans gluten : remplacez le pain par des flocons de pomme de terre et la semoule par du riz.']::text[], 'Réfrigérateur : 24 h. Les boulettes en sauce se congèlent 1 mois.', array['Poisson en conserve : vérifiez du bout des doigts qu’il ne reste aucune arête dure (retirez l’arête centrale des sardines).','Avant 4 ans : boulettes coupées en morceaux.']::text[], 'Les sardines en conserve apportent des protéines et des oméga-3.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
