insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-boulettes-sardines-sauce-tomate-semoule' and owner_id is null), 2, 'Émiettez le pain de mie et mélangez-le avec les sardines, l’œuf et le persil. Formez une vingtaine de petites boulettes.') on conflict do nothing;
