insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-spaghetti-sardines-citron-chapelure' and owner_id is null), 1, 'Émincez très finement le fenouil et faites-le cuire 10 minutes à la poêle dans une cuillerée d’huile avec l’ail écrasé, à couvert, jusqu’à ce qu’il soit fondant.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-spaghetti-sardines-citron-chapelure' and owner_id is null), 2, 'Faites dorer la chapelure 2 minutes à sec dans une autre poêle, en remuant.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-spaghetti-sardines-citron-chapelure' and owner_id is null), 3, 'Faites cuire les pâtes selon le temps indiqué sur le paquet. Pour les plus jeunes, cassez les spaghetti en trois avant cuisson.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-spaghetti-sardines-citron-chapelure' and owner_id is null), 4, 'Retirez l’arête centrale des sardines, vérifiez qu’il ne reste aucune arête dure, et émiettez-les dans le fenouil avec le zeste du citron. Faites chauffer 2 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-spaghetti-sardines-citron-chapelure' and owner_id is null), 5, 'Mélangez avec les pâtes, le reste d’huile, un peu de jus de citron et le persil. Parsemez de chapelure au moment de servir.') on conflict do nothing;
