insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-lasagnes-saumon-epinards-ricotta', 'Lasagnes au saumon, épinards et ricotta', 'Des lasagnes blanches et vertes, moelleuses et sans viande.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 25, 55, array['gluten','eggs','fish','milk']::text[], array['family','batch','freezer','calcium','vegetables']::text[], array['Sans gluten : feuilles de lasagnes sans gluten et béchamel liée à la fécule de maïs.','Le saumon peut être remplacé par du poisson blanc.']::text[], 'Réfrigérateur : 48 h. Se congèle en parts 2 mois si le saumon était frais.', array['Poisson : passez les doigts sur toute la chair, avant et après cuisson, et retirez la moindre arête.','Avant 5 ans : fromages au lait pasteurisé ou pâtes pressées cuites uniquement.']::text[], 'La ricotta et le lait apportent du calcium ; le saumon, des protéines.', 3, array['autumn','winter','spring']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
