insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-lasagnes-saumon-epinards-ricotta' and owner_id is null), 2, 'Coupez le saumon en fines lamelles en retirant la peau et en vérifiant qu’il ne reste aucune arête.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-lasagnes-saumon-epinards-ricotta' and owner_id is null), 3, 'Préparez une béchamel : beurre fondu, farine, puis le lait en fouettant jusqu’à épaississement ; ajoutez la muscade.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-lasagnes-saumon-epinards-ricotta' and owner_id is null), 4, 'Préchauffez le four à 190 °C. Dans un plat, alternez béchamel, feuilles de lasagnes, épinards à la ricotta et saumon ; terminez par feuilles et béchamel.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-lasagnes-saumon-epinards-ricotta' and owner_id is null), 5, 'Enfournez 35 à 40 minutes : les pâtes doivent être tendres sous la pointe d’un couteau et le saumon cuit à cœur. Laissez reposer 5 minutes avant de couper.') on conflict do nothing;
