insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-risotto-crevettes-petits-pois', 'Risotto crémeux aux crevettes et petits pois', 'Un risotto doux et onctueux, à remuer avec les enfants.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 10, 25, array['gluten','crustaceans','milk','celery']::text[], array['family','protein','picky']::text[], array['Allergie aux crustacés : remplacez les crevettes par des dés de cabillaud cuits 5 minutes dans le risotto.','Sans lait : sans parmesan, avec un filet d’huile d’olive.']::text[], 'À manger aussitôt ; 24 h au réfrigérateur, réchauffez avec un peu d’eau jusqu’à ce que ce soit bien chaud. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Avant 4 ans : coupez les crevettes en petits morceaux (elles sont fermes et peuvent bloquer la gorge).','Avant 5 ans : fromages au lait pasteurisé ou pâtes pressées cuites uniquement.']::text[], 'Les crevettes apportent des protéines ; les petits pois, des fibres.', 3, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
