insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-risotto-crevettes-petits-pois' and owner_id is null), 1, 'Faites chauffer le bouillon et gardez-le frémissant. Émincez finement l’oignon.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-risotto-crevettes-petits-pois' and owner_id is null), 2, 'Faites revenir l’oignon 3 minutes dans l’huile, ajoutez le riz et remuez 1 minute jusqu’à ce qu’il devienne nacré.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-risotto-crevettes-petits-pois' and owner_id is null), 3, 'Versez le bouillon louche par louche en remuant, en attendant qu’il soit absorbé avant d’en ajouter. Comptez 18 minutes en tout ; ajoutez les petits pois à mi-cuisson.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-risotto-crevettes-petits-pois' and owner_id is null), 4, 'Coupez les crevettes en morceaux (en petits morceaux avant 4 ans), ajoutez-les les 3 dernières minutes pour qu’elles soient bien chaudes à cœur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-risotto-crevettes-petits-pois' and owner_id is null), 5, 'Hors du feu, incorporez le parmesan et servez aussitôt.') on conflict do nothing;
