insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-riz-cantonais-crevettes-oeuf', 'Riz sauté aux crevettes, œuf et petits légumes', 'Une façon de cuisiner le riz de la veille, à la poêle.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 20, array['gluten','crustaceans','eggs','soy']::text[], array['world','family','protein','make_ahead']::text[], array['Allergie aux crustacés : remplacez les crevettes par des dés de poulet cuits à cœur.','Sans soja ni gluten : omettez la sauce soja et ajoutez un peu de ciboulette.']::text[], 'Le riz cuit se garde 24 h au réfrigérateur, refroidi rapidement ; réchauffez une seule fois, à cœur. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Avant 4 ans : coupez les crevettes en petits morceaux (elles sont fermes et peuvent bloquer la gorge).']::text[], 'Un plat complet avec un féculent, des œufs, des crevettes et des légumes.', 2, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
