insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-paella-douce-poisson-crevettes' and owner_id is null), 1, 'Émincez l’oignon et coupez le poivron en petits dés.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-paella-douce-poisson-crevettes' and owner_id is null), 2, 'Faites-les revenir 5 minutes dans l’huile d’olive, ajoutez le riz, le curcuma et les tomates concassées, puis 700 ml d’eau chaude.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-paella-douce-poisson-crevettes' and owner_id is null), 3, 'Laissez cuire 15 minutes à feu doux, sans remuer, en ajoutant les petits pois à mi-cuisson.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-paella-douce-poisson-crevettes' and owner_id is null), 4, 'Coupez le cabillaud en cubes en retirant toutes les arêtes, enfoncez-les dans le riz avec les crevettes coupées en morceaux, couvrez et laissez cuire encore 6 minutes : la chair doit être opaque jusqu’au centre et s’effeuiller facilement à la fourchette.') on conflict do nothing;
