insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-curry-doux-cabillaud-coco-carottes', 'Curry doux de cabillaud au lait de coco et carottes', 'Une sauce jaune parfumée, sans piquant, avec du riz.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 25, array['fish','celery','mustard']::text[], array['world','protein','family','vegetables']::text[], array['Le curry doux peut contenir de la moutarde et du céleri : vérifiez l’étiquette en cas d’allergie.','Pour les plus petits, émiettez le poisson dans la sauce.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud au centre. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Poisson : passez les doigts sur toute la chair, avant et après cuisson, et retirez la moindre arête.']::text[], 'Le poisson apporte des protéines, les carottes et le riz complètent l’assiette.', 2, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
