insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-nouilles-saumon-brocoli-sesame', 'Nouilles de riz sautées au saumon et brocoli', 'Un wok doux, avec des nouilles faciles à attraper à la fourchette.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 20, array['gluten','fish','soy','sesame']::text[], array['world','protein','vegetables','quick']::text[], array['Sans soja ni sésame : remplacez la sauce soja par un trait de citron et omettez les graines.','Avant 4 ans : carottes bien tendres, coupées très finement.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud au centre.', array['Poisson : passez les doigts sur toute la chair, avant et après cuisson, et retirez la moindre arête.']::text[], 'Le saumon apporte des protéines ; le brocoli et les carottes, des légumes.', 3, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
