insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-nouilles-saumon-brocoli-sesame' and owner_id is null), 2, 'Détaillez le brocoli en petits bouquets et faites-le cuire 5 minutes à l’eau bouillante. Épluchez les carottes et coupez-les en julienne.') on conflict do nothing;
