insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'po-moules-creme-frites-four' and owner_id is null), 6, 'olive_oil', 'huile d''olive', 2, 'cs', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-moules-creme-frites-four' and owner_id is null), 1, 'Préchauffez le four à 210 °C. Épluchez les pommes de terre, coupez-les en frites, mélangez-les avec l’huile d’olive et enfournez 35 minutes en les retournant à mi-cuisson.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-moules-creme-frites-four' and owner_id is null), 2, 'Grattez et rincez les moules ; jetez celles qui sont cassées ou qui restent ouvertes quand on les tapote.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-moules-creme-frites-four' and owner_id is null), 3, 'Faites suer les échalotes émincées 3 minutes dans une grande cocotte, ajoutez les moules, couvrez et faites cuire 6 à 8 minutes à feu vif en secouant la cocotte.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-moules-creme-frites-four' and owner_id is null), 4, 'Les moules sont cuites quand elles sont toutes ouvertes et que leur chair est ferme et chaude : jetez celles qui restent fermées.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-moules-creme-frites-four' and owner_id is null), 5, 'Ajoutez la crème et le persil, mélangez et servez avec les frites. Décoquillez les moules pour les plus jeunes.') on conflict do nothing;
