insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-moules-tomate-coquillettes', 'Moules décoquillées à la tomate et coquillettes', 'Les moules sans coquilles, mélangées aux pâtes dans une sauce tomate.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 36, 120, array['regular']::text[], 4, null, 20, 25, array['gluten','molluscs']::text[], array['family','iron','budget','protein']::text[], array['Avant 4 ans : coupez les moules en petits morceaux.','Le jus des moules est salé : inutile d’ajouter du sel.']::text[], 'À manger aussitôt.', array['Moules : jetez celles qui restent ouvertes avant cuisson ou fermées après cuisson ; avant 4 ans, décoquillez-les et coupez-les en morceaux.']::text[], 'Les moules apportent des protéines et du fer ; les pâtes, un féculent.', 1, array['summer','autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'po-moules-tomate-coquillettes' and owner_id is null), 1, 'mussels', 'moules', 1000, 'g', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'po-moules-tomate-coquillettes' and owner_id is null), 2, 'canned_tomato', 'tomates concassées en conserve', 400, 'g', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'po-moules-tomate-coquillettes' and owner_id is null), 3, 'garlic', 'ail', 1, 'u', 'gousse', false) on conflict do nothing;
