insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'po-moules-tomate-coquillettes' and owner_id is null), 6, 'olive_oil', 'huile d''olive', 1, 'cs', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-moules-tomate-coquillettes' and owner_id is null), 1, 'Grattez et rincez les moules, en éliminant celles qui sont cassées ou ouvertes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-moules-tomate-coquillettes' and owner_id is null), 2, 'Faites-les cuire 6 minutes dans une cocotte couverte, à feu vif, jusqu’à ce qu’elles soient toutes ouvertes. Jetez celles qui restent fermées et décoquillez les autres.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-moules-tomate-coquillettes' and owner_id is null), 3, 'Faites revenir l’ail écrasé 1 minute dans l’huile, ajoutez les tomates concassées et un peu du jus des moules filtré, puis laissez mijoter 10 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-moules-tomate-coquillettes' and owner_id is null), 4, 'Faites cuire les pâtes selon le temps indiqué sur le paquet.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-moules-tomate-coquillettes' and owner_id is null), 5, 'Ajoutez les moules à la sauce, réchauffez 2 minutes jusqu’à ce que tout soit bien chaud, puis mélangez avec les pâtes et le basilic.') on conflict do nothing;
