insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-soupe-poisson-legumes-vermicelles', 'Soupe de poisson aux légumes et vermicelles', 'Un bouillon clair avec des morceaux de poisson tendres et des petites pâtes.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 30, array['gluten','fish']::text[], array['family','protein','vegetables','budget']::text[], array['Sans gluten : remplacez les vermicelles par du riz.','Pour les plus jeunes, mixez une partie des légumes pour épaissir.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud au centre.', array['Poisson : passez les doigts sur toute la chair, avant et après cuisson, et retirez la moindre arête.']::text[], 'Une soupe complète avec poisson, légumes et féculents.', 1, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
