insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'po-soupe-poisson-legumes-vermicelles' and owner_id is null), 7, 'bay_leaf', 'feuille de laurier', 1, 'u', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'po-soupe-poisson-legumes-vermicelles' and owner_id is null), 8, 'olive_oil', 'huile d''olive', 1, 'cs', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-soupe-poisson-legumes-vermicelles' and owner_id is null), 1, 'Épluchez les carottes et les pommes de terre, lavez le poireau ; coupez le tout en petits dés. Coupez les tomates en morceaux.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-soupe-poisson-legumes-vermicelles' and owner_id is null), 2, 'Faites revenir le poireau 3 minutes dans l’huile, ajoutez les autres légumes, la feuille de laurier et 1,2 litre d’eau. Laissez cuire 20 minutes à frémissements.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-soupe-poisson-legumes-vermicelles' and owner_id is null), 3, 'Coupez le cabillaud en petits cubes en vérifiant qu’il ne reste aucune arête.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-soupe-poisson-legumes-vermicelles' and owner_id is null), 4, 'Ajoutez les vermicelles et le poisson, et laissez cuire 5 minutes : la chair doit être opaque jusqu’au centre et s’effeuiller facilement à la fourchette. Retirez le laurier avant de servir.') on conflict do nothing;
