insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-veloute-potiron-crevettes', 'Velouté de potiron et crevettes au lait de coco', 'Un velouté orange avec des morceaux de crevettes, un peu exotique.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 25, array['crustaceans']::text[], array['vegetables','family','world']::text[], array['Allergie aux crustacés : servez avec des dés de poisson blanc pochés 5 minutes dans le velouté.','Le lait de coco peut être remplacé par de la crème.']::text[], 'Le velouté seul se garde 48 h et se congèle ; ajoutez les crevettes au moment de servir.', array['Avant 4 ans : coupez les crevettes en petits morceaux (elles sont fermes et peuvent bloquer la gorge).']::text[], 'Le potiron apporte des fibres ; les crevettes, des protéines.', 2, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
