insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'po-veloute-potiron-crevettes' and owner_id is null), 7, 'chives', 'ciboulette', 1, 'cs', 'ciselée', false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-veloute-potiron-crevettes' and owner_id is null), 1, 'Épluchez le potiron et la pomme de terre et coupez-les en cubes ; émincez l’oignon.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-veloute-potiron-crevettes' and owner_id is null), 2, 'Faites revenir l’oignon 3 minutes dans l’huile, ajoutez les légumes et couvrez d’eau. Laissez cuire 20 minutes, jusqu’à ce qu’ils soient tendres.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-veloute-potiron-crevettes' and owner_id is null), 3, 'Mixez finement avec le lait de coco.') on conflict do nothing;
