insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-salade-riz-thon-concombre-oeuf', 'Salade de riz au thon, concombre et œuf dur', 'Une salade complète pour les beaux jours et la boîte à repas.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 15, array['eggs','fish']::text[], array['lunchbox','make_ahead','protein','budget']::text[], array['Sans poisson : remplacez le thon par des pois chiches.','Le riz peut être remplacé par du boulgour.']::text[], '24 h au réfrigérateur ; dans une boîte isotherme avec un pain de glace pour l’école. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Poisson en conserve : vérifiez du bout des doigts qu’il ne reste aucune arête dure (retirez l’arête centrale des sardines).','Gardez au frais jusqu’au repas (chaîne du froid).']::text[], 'Du riz, deux sources de protéines et des légumes crus.', 1, array['spring','summer']::text[], 'cold', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
