insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-salade-boulgour-crevettes-menthe', 'Salade de boulgour aux crevettes, concombre et menthe', 'Une salade façon taboulé, avec des crevettes en morceaux.', array['child','family']::text[], array['lunch']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 10, array['gluten','crustaceans']::text[], array['lunchbox','quick','make_ahead','world']::text[], array['Sans gluten : utilisez du quinoa.','Allergie aux crustacés : remplacez par du thon en conserve ou des pois chiches.']::text[], '24 h au réfrigérateur ; avec un pain de glace dans la boîte à repas.', array['Gardez au frais jusqu’au repas (chaîne du froid).','Avant 4 ans : coupez les crevettes en petits morceaux (elles sont fermes et peuvent bloquer la gorge).']::text[], 'Le boulgour est un féculent riche en fibres ; les crevettes apportent des protéines.', 2, array['spring','summer']::text[], 'cold', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
