insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-galettes-sarrasin-saumon-epinards' and owner_id is null), 2, 'Faites cuire les épinards 8 minutes à la poêle jusqu’à ce que l’eau s’évapore, puis ajoutez la crème.') on conflict do nothing;
