insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-truite-amandes-haricots-verts-pommes-de-terre', 'Truite à la poudre d’amande, haricots verts et pommes de terre', 'La truite aux amandes revisitée, avec de la poudre pour les petits.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 25, array['fish','milk','nuts']::text[], array['protein','family','vegetables']::text[], array['Allergie aux fruits à coque : remplacez la poudre d’amande par de la farine ou de la chapelure.','Avant 4 ans : jamais d’amandes entières ou effilées, seulement la poudre.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud au centre.', array['Poisson : passez les doigts sur toute la chair, avant et après cuisson, et retirez la moindre arête.']::text[], 'La truite apporte des protéines et des oméga-3 ; les légumes complètent l’assiette.', 3, array['spring','summer']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
