insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-truite-amandes-haricots-verts-pommes-de-terre' and owner_id is null), 3, 'Faites fondre le beurre dans une poêle et faites cuire les filets 3 à 4 minutes de chaque côté, à feu moyen : la chair doit être opaque jusqu’au centre et s’effeuiller facilement à la fourchette.') on conflict do nothing;
