insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-maquereau-moutarde-carottes-semoule', 'Maquereau rôti à la moutarde douce, carottes au cumin et semoule', 'Le maquereau, moelleux et doux, sous une fine couche de moutarde.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 25, array['gluten','fish','mustard']::text[], array['protein','budget','vegetables','world']::text[], array['Sans moutarde : badigeonnez simplement d’un peu de citron.','Sans gluten : remplacez la semoule par du riz.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud au centre.', array['Poisson : passez les doigts sur toute la chair, avant et après cuisson, et retirez la moindre arête.']::text[], 'Le maquereau est un poisson gras riche en oméga-3.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
