insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-maquereau-moutarde-carottes-semoule' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Épluchez les carottes, coupez-les en bâtonnets, mélangez-les avec l’huile d’olive et le cumin et enfournez 25 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-maquereau-moutarde-carottes-semoule' and owner_id is null), 2, 'Vérifiez les filets de maquereau du bout des doigts et retirez toutes les arêtes. Badigeonnez la chair de moutarde.') on conflict do nothing;
