insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-gnocchis-saumon-courgettes-basilic', 'Gnocchis poêlés au saumon, courgettes et fromage frais', 'Des gnocchis dorés, une sauce fondante et des dés de saumon.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 10, 15, array['gluten','fish','milk']::text[], array['quick','protein','family','vegetables']::text[], array['Avant 4 ans : coupez les gnocchis en deux.','Le saumon peut être remplacé par du thon en conserve.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud au centre.', array['Poisson : passez les doigts sur toute la chair, avant et après cuisson, et retirez la moindre arête.','Avant 4 ans : gnocchis coupés en deux.','Avant 5 ans : fromages au lait pasteurisé ou pâtes pressées cuites uniquement.']::text[], 'Les gnocchis apportent un féculent ; le saumon, des protéines.', 3, array['summer']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
