insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-poisson-epices-douces-frites-patate-douce-yaourt', 'Poisson aux épices douces, frites de patate douce et sauce yaourt', 'Des frites orange au four et un poisson parfumé au paprika et au cumin.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 30, array['fish','milk']::text[], array['picky','protein','family','vegetables']::text[], array['Sans lait : remplacez le yaourt par une sauce à l’avocat écrasé et au citron.']::text[], 'À manger aussitôt ; 24 h au réfrigérateur.', array['Poisson : passez les doigts sur toute la chair, avant et après cuisson, et retirez la moindre arête.']::text[], 'La patate douce apporte des fibres ; le poisson, des protéines.', 2, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
