insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-poisson-epices-douces-frites-patate-douce-yaourt' and owner_id is null), 2, 'Préchauffez le four à 210 °C. Épluchez les patates douces, coupez-les en frites, mélangez-les avec 2 cuillerées d’huile et enfournez 30 minutes.') on conflict do nothing;
