insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('po-crevettes-sautees-riz-ananas', 'Riz aux crevettes, ananas et poivron', 'Un plat sucré-salé coloré, inspiré de la cuisine thaïe, sans piment.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 20, array['crustaceans']::text[], array['world','quick','family']::text[], array['Allergie aux crustacés : remplacez les crevettes par des dés de poulet cuits à cœur.','Le riz peut être remplacé par des nouilles de riz.']::text[], 'Réfrigérateur : 24 h dans une boîte fermée ; réchauffez une seule fois, jusqu’à ce que ce soit bien chaud au centre. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Avant 4 ans : coupez les crevettes en petits morceaux (elles sont fermes et peuvent bloquer la gorge).']::text[], 'Les crevettes apportent des protéines, l’ananas et le poivron de la couleur et des fibres.', 3, array['spring','summer']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
