insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'po-crevettes-sautees-riz-ananas' and owner_id is null), 2, 'Émincez l’oignon, coupez le poivron et l’ananas en petits dés.') on conflict do nothing;
