insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-dahl-lentilles-corail-coco-riz', 'Dahl doux de lentilles corail au lait de coco et riz', 'Un dahl onctueux et peu épicé, servi avec du riz pour associer légumineuse et céréale.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 30, array['celery','mustard']::text[], array['vegetarian','protein','iron','fiber','batch','freezer','world','budget']::text[], array['Allergie à la moutarde ou au céleri : remplacez le curry par du curcuma et une pointe de cumin (vérifiez l’étiquette du mélange d’épices).','Pour la famille, ajoutez de la coriandre fraîche et un peu de piment dans les assiettes des adultes.']::text[], '3 jours au réfrigérateur ; le dahl se congèle très bien en portions (3 mois). Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Vérifiez la température avant de servir : le dahl garde longtemps la chaleur.']::text[], 'Les lentilles et le riz réunis apportent des protéines végétales complémentaires, ainsi que des fibres.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
