insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-dahl-lentilles-corail-coco-riz' and owner_id is null), 1, 'Rincez les lentilles corail à l’eau froide jusqu’à ce que l’eau soit claire.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-dahl-lentilles-corail-coco-riz' and owner_id is null), 2, 'Émincez finement l’oignon et coupez la carotte en petits dés. Faites-les revenir 5 minutes dans l’huile, à feu doux, puis ajoutez le curry et mélangez 1 minute.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-dahl-lentilles-corail-coco-riz' and owner_id is null), 3, 'Ajoutez les lentilles, les tomates concassées, le lait de coco et 500 ml d’eau. Laissez mijoter 20 minutes à couvert en remuant de temps en temps, jusqu’à ce que les lentilles se défassent.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-dahl-lentilles-corail-coco-riz' and owner_id is null), 4, 'Pendant ce temps, faites cuire le riz dans une grande casserole d’eau selon le temps indiqué sur le paquet, puis égouttez-le.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-dahl-lentilles-corail-coco-riz' and owner_id is null), 5, 'Servez le dahl sur le riz ; pour les plus jeunes, écrasez légèrement les morceaux de carotte à la fourchette.') on conflict do nothing;
