insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-curry-pois-chiches-epinards-riz-complet', 'Curry doux de pois chiches aux épinards et riz complet', 'Un curry tout doux, coloré au curcuma, où les pois chiches fondent dans une sauce coco.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 40, array[]::text[], array['vegetarian','protein','fiber','iron','vegetables','world','batch']::text[], array['Version plus rapide : utilisez du riz blanc (15 minutes de cuisson).','Pour les adultes, relevez avec du gingembre ou du piment dans l’assiette.']::text[], '3 jours au réfrigérateur dans une boîte fermée ; le curry se congèle (sans le riz) jusqu’à 3 mois. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Avant 4 ans, écrasez légèrement les pois chiches : ils sont ronds et fermes.']::text[], 'Les pois chiches et le riz complet apportent ensemble des protéines végétales et des fibres ; les épinards ajoutent un légume.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
