insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-curry-pois-chiches-epinards-riz-complet' and owner_id is null), 1, 'Faites cuire le riz complet dans un grand volume d’eau 35 à 40 minutes (ou selon le paquet), puis égouttez.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-curry-pois-chiches-epinards-riz-complet' and owner_id is null), 2, 'Pendant ce temps, émincez l’oignon et l’ail. Faites-les revenir 5 minutes dans l’huile d’olive avec le curcuma et le cumin.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-curry-pois-chiches-epinards-riz-complet' and owner_id is null), 3, 'Ajoutez les épinards encore surgelés et laissez-les fondre 5 minutes en remuant.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-curry-pois-chiches-epinards-riz-complet' and owner_id is null), 4, 'Versez les pois chiches et le lait de coco, puis laissez mijoter 10 minutes à feu doux. Pour les enfants de moins de 4 ans, écrasez grossièrement une partie des pois chiches à la fourchette.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-curry-pois-chiches-epinards-riz-complet' and owner_id is null), 5, 'Servez le curry avec le riz.') on conflict do nothing;
