insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-boulettes-lentilles-sauce-tomate-pates', 'Boulettes de lentilles à la sauce tomate et coquillettes', 'Des boulettes moelleuses façon « spaghetti boulettes », entièrement végétales et au fromage.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 25, 40, array['gluten','eggs','milk']::text[], array['vegetarian','protein','iron','fiber','freezer','family','picky']::text[], array['Sans œuf : remplacez l’œuf par 2 cuillères à soupe de fromage blanc et un peu plus d’avoine.','Les boulettes se congèlent crues ou cuites.']::text[], '3 jours au réfrigérateur ; boulettes congelées jusqu’à 3 mois.', array['Œuf cuit à cœur : les boulettes doivent être fermes au centre.']::text[], 'Les lentilles associées aux pâtes et à l’avoine forment un plat complet en protéines végétales, complété par le fromage.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
