insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-boulettes-lentilles-sauce-tomate-pates' and owner_id is null), 1, 'Faites cuire les lentilles vertes 25 minutes dans de l’eau non salée, égouttez-les bien et laissez tiédir.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-boulettes-lentilles-sauce-tomate-pates' and owner_id is null), 2, 'Mixez grossièrement les lentilles avec les flocons d’avoine, l’œuf, l’emmental râpé et la moitié de l’oignon finement haché. Formez une vingtaine de petites boulettes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-boulettes-lentilles-sauce-tomate-pates' and owner_id is null), 3, 'Faites dorer les boulettes 8 à 10 minutes dans 1 cuillère d’huile, en les retournant, jusqu’à ce qu’elles soient fermes et cuites à cœur.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-boulettes-lentilles-sauce-tomate-pates' and owner_id is null), 4, 'Dans une autre casserole, faites revenir le reste de l’oignon dans l’huile restante, ajoutez les tomates concassées et les herbes de Provence, puis laissez mijoter 10 minutes. Déposez les boulettes dans la sauce.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-boulettes-lentilles-sauce-tomate-pates' and owner_id is null), 5, 'Faites cuire les pâtes selon le paquet, égouttez-les et servez avec les boulettes en sauce, coupées en deux pour les plus petits.') on conflict do nothing;
