insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-galettes-pois-chiches-courgette-sauce-ciboulette', 'Galettes poêlées de pois chiches à la courgette, sauce ciboulette', 'Des galettes moelleuses aux pois chiches et à la courgette râpée, avec une sauce fraîche au fromage blanc.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 25, 20, array['gluten','eggs','milk']::text[], array['vegetarian','protein','fiber','finger','lunchbox','vegetables']::text[], array['Sans œuf : remplacez l’œuf par 2 cuillères à soupe de fromage blanc et un peu plus d’avoine.','Servez avec du boulgour ou du riz pour un repas plus copieux.']::text[], 'Galettes : 2 jours au réfrigérateur ou 2 mois au congélateur. Sauce : 24 h au frais.', array['Œuf cuit à cœur : les galettes doivent être fermes au centre.']::text[], 'Les pois chiches et l’avoine associent légumineuse et céréale ; le fromage blanc ajoute du calcium.', 1, array['spring','summer']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
