insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-galettes-pois-chiches-courgette-sauce-ciboulette' and owner_id is null), 2, 'Écrasez finement les pois chiches à la fourchette ou au mixeur, puis mélangez-les avec la courgette, l’œuf, les flocons d’avoine et le paprika. Laissez reposer 10 minutes pour que l’avoine gonfle.') on conflict do nothing;
