insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-tortilla-pommes-de-terre-courgette', 'Tortilla épaisse aux pommes de terre et courgette', 'Une omelette espagnole bien prise, qui se mange chaude ou froide, en parts ou en cubes.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 35, array['eggs']::text[], array['vegetarian','protein','budget','lunchbox','finger','world']::text[], array['Remplacez la courgette par des poivrons ou des épinards selon la saison.','Sans sel pour toute la famille : ajoutez des herbes à la place.']::text[], '2 jours au réfrigérateur, bien emballée.', array['Œufs cuits à cœur : piquez le centre, aucune partie ne doit couler.']::text[], 'Les œufs apportent des protéines et les pommes de terre des féculents : un plat complet avec une salade.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
