insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-tortilla-pommes-de-terre-courgette' and owner_id is null), 1, 'Épluchez les pommes de terre et coupez-les en fines lamelles ; coupez la courgette en demi-rondelles et émincez l’oignon.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-tortilla-pommes-de-terre-courgette' and owner_id is null), 2, 'Faites cuire les légumes 20 minutes à feu doux dans l’huile d’olive, à couvert, jusqu’à ce que les pommes de terre soient tendres.') on conflict do nothing;
