insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-tortilla-pommes-de-terre-courgette' and owner_id is null), 4, 'Retournez la tortilla à l’aide d’une assiette et poursuivez la cuisson 5 minutes : les œufs doivent être cuits à cœur, sans partie liquide.') on conflict do nothing;
