insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-gratin-pates-completes-chou-fleur-comte', 'Gratin de pâtes complètes au chou-fleur et au comté', 'Un gratin crémeux où le chou-fleur se cache dans une béchamel au comté.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 35, array['gluten','milk']::text[], array['vegetarian','calcium','protein','fiber','family','picky']::text[], array['Remplacez le comté par de l’emmental ; ajoutez des pois chiches pour plus de protéines végétales.','Les plus jeunes peuvent avoir le chou-fleur écrasé dans la sauce.']::text[], '2 jours au réfrigérateur ; réchauffez au four avec un peu de lait.', array[]::text[], 'Le comté et le lait apportent du calcium et des protéines ; les pâtes complètes, des fibres.', 2, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
