insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-gratin-pates-completes-chou-fleur-comte' and owner_id is null), 1, 'Préchauffez le four à 200 °C. Détaillez le chou-fleur en petits bouquets et faites-les cuire 5 minutes avec les pâtes dans une grande casserole d’eau (temps total selon le paquet). Égouttez.') on conflict do nothing;
