insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-chili-doux-haricots-rouges-riz-complet', 'Chili doux aux haricots rouges, maïs et riz complet', 'Un chili sans piment, parfumé au paprika doux, avec une cuillère de fromage blanc.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 40, array['milk']::text[], array['vegetarian','protein','fiber','iron','batch','freezer','world']::text[], array['Pour les adultes, ajoutez du piment dans l’assiette.','Sans lait : remplacez le fromage blanc par un dé d’avocat.']::text[], '3 jours au réfrigérateur ; le chili se congèle 3 mois. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Avant 4 ans, écrasez les haricots et les grains de maïs.']::text[], 'Les haricots rouges et le riz complet associés fournissent des protéines végétales et beaucoup de fibres.', 1, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
