insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-soupe-pois-casses-carottes-croutons', 'Soupe veloutée de pois cassés aux carottes et croûtons', 'Une soupe épaisse et réconfortante, servie avec des croûtons de pain complet.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 50, array['gluten','milk']::text[], array['vegetarian','protein','fiber','iron','budget','batch','freezer']::text[], array['Sans lait : supprimez la crème ou remplacez-la par un filet d’huile d’olive.','Pour les moins de 3 ans, servez sans croûtons ou avec des croûtons ramollis dans la soupe.']::text[], '3 jours au réfrigérateur ; se congèle 3 mois (sans les croûtons).', array['Retirez bien la feuille de laurier avant de mixer.']::text[], 'Les pois cassés et le pain complet réunissent légumineuse et céréale ; la soupe apporte des fibres.', 1, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
