insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-galettes-sarrasin-oeuf-epinards-emmental', 'Galettes de sarrasin à l’œuf, aux épinards et à l’emmental', 'Des galettes bretonnes garnies d’un œuf bien cuit, d’épinards et de fromage fondu.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 30, array['eggs','milk']::text[], array['vegetarian','protein','iron','calcium','family','world']::text[], array['Sans œuf sur la galette : remplacez-le par des dés de tofu ou du fromage frais.','Vérifiez l’étiquette de la farine de sarrasin en cas d’allergie au blé.']::text[], 'Pâte : 24 h au réfrigérateur. Les galettes garnies se mangent aussitôt.', array['Œuf cuit à cœur : jaune bien pris pour les enfants.']::text[], 'L’œuf et l’emmental apportent des protéines et du calcium ; le sarrasin, des féculents.', 2, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
