insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-polenta-cremeuse-ragout-lentilles', 'Polenta crémeuse et ragoût de lentilles aux carottes', 'Une polenta moelleuse au parmesan, nappée d’un ragoût de lentilles mijoté.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 35, array['milk']::text[], array['vegetarian','protein','iron','fiber','batch']::text[], array['La polenta refroidie se coupe en bâtonnets à faire dorer le lendemain.','Sans lait : remplacez le parmesan par un filet d’huile d’olive.']::text[], 'Ragoût : 3 jours au réfrigérateur ou 3 mois au congélateur. Polenta : 2 jours au frais.', array[]::text[], 'Les lentilles et la polenta associent légumineuse et céréale ; le parmesan ajoute du calcium.', 1, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
