insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-polenta-cremeuse-ragout-lentilles' and owner_id is null), 1, 'Émincez l’oignon, coupez les carottes en petits dés et faites-les revenir 5 minutes dans 1 cuillère d’huile d’olive.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-polenta-cremeuse-ragout-lentilles' and owner_id is null), 2, 'Ajoutez les lentilles, les tomates concassées, le thym et 400 ml d’eau. Laissez mijoter 30 minutes, jusqu’à ce que les lentilles soient tendres.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-polenta-cremeuse-ragout-lentilles' and owner_id is null), 3, 'Portez 900 ml d’eau à ébullition, versez la polenta en pluie en fouettant et laissez cuire 5 minutes (polenta instantanée) en remuant.') on conflict do nothing;
