insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-tofu-saute-brocoli-nouilles-riz' and owner_id is null), 1, 'Coupez le tofu en petits dés et épongez-le. Détaillez le brocoli en petits bouquets et taillez les carottes en fines lamelles.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-tofu-saute-brocoli-nouilles-riz' and owner_id is null), 2, 'Faites dorer le tofu 6 à 8 minutes dans 1 cuillère d’huile, puis réservez.') on conflict do nothing;
