insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-oeufs-cocotte-epinards-mouillettes', 'Œufs cocotte aux épinards et mouillettes de pain complet', 'Des œufs au four bien pris sur un lit d’épinards à la crème.', array['child','family']::text[], array['dinner','breakfast']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 10, 20, array['gluten','eggs','milk']::text[], array['vegetarian','protein','iron','calcium','quick']::text[], array['Les adultes peuvent garder le jaune coulant ; pour les enfants, il doit être pris.','Remplacez les épinards par des poireaux fondus.']::text[], 'À consommer aussitôt.', array['Jaune bien pris pour les enfants ; ramequins très chauds à la sortie du four.']::text[], 'L’œuf apporte des protéines ; le pain complet, des fibres ; les épinards, un légume.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
