insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-riz-complet-saute-oeuf-tofu-petits-pois', 'Riz complet sauté à l’œuf, au tofu et aux petits pois', 'Un riz sauté façon cantonais, sans viande, idéal pour finir un reste de riz.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 36, 120, array['regular']::text[], 4, null, 15, 40, array['gluten','eggs','soy']::text[], array['vegetarian','protein','fiber','world','budget']::text[], array['Allergie au soja : supprimez le tofu et la sauce soja, ajoutez un œuf de plus.','Avant 4 ans, écrasez légèrement les petits pois.']::text[], 'Riz cuit : à refroidir vite et à garder au réfrigérateur 24 h au maximum. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Refroidissez rapidement le riz cuit et ne le gardez pas à température ambiante.','Œufs cuits à cœur.']::text[], 'L’œuf et le tofu apportent des protéines ; le riz complet, des fibres.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
