insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-wraps-haricots-rouges-avocat-mais', 'Wraps tièdes aux haricots rouges, avocat et maïs', 'Des wraps à garnir soi-même, avec une purée de haricots rouges au cumin.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 36, 120, array['regular']::text[], 4, null, 15, 10, array['gluten','milk']::text[], array['vegetarian','protein','fiber','quick','world','finger']::text[], array['Pour les moins de 4 ans, écrasez aussi le maïs ou remplacez-le par des dés de tomate.','Sans lait : supprimez l’emmental.']::text[], 'À préparer au dernier moment ; la purée de haricots se garde 2 jours au réfrigérateur.', array['Avant 4 ans, coupez les wraps en petits tronçons et écrasez les grains de maïs.']::text[], 'Les haricots rouges et la galette de blé associent légumineuse et céréale ; l’avocat apporte des matières grasses insaturées.', 2, array['spring','summer']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
