insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-gratin-riz-complet-courgettes-oeufs', 'Gratin de riz complet aux courgettes, lié à l’œuf', 'Un gratin moelleux qui se coupe en parts, chaud ou tiède.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 20, 45, array['eggs','milk']::text[], array['vegetarian','protein','calcium','vegetables','lunchbox','batch']::text[], array['Remplacez les courgettes par des épinards ou du potiron.','Ajoutez des lentilles corail cuites pour plus de protéines végétales.']::text[], '2 jours au réfrigérateur ; se réchauffe au four. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Œufs cuits à cœur.']::text[], 'Le riz complet, les œufs et l’emmental composent un plat complet avec un légume.', 1, array['summer','autumn']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
