insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-houmous-betterave-batonnets-pita', 'Houmous rose à la betterave, bâtonnets et pain pita', 'Une trempette rose vif à préparer sans cuisson pour le goûter ou l’apéritif familial.', array['child','family']::text[], array['snack','lunch']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 0, array['gluten','sesame']::text[], array['vegetarian','protein','fiber','quick','finger','vegetables']::text[], array['Allergie au sésame : supprimez le tahini et ajoutez une cuillère d’huile d’olive.','Remplacez la betterave par de la carotte cuite pour un houmous orange.']::text[], '3 jours au réfrigérateur dans une boîte fermée.', array['Avant 4 ans, préférez des bâtonnets de concombre fins et tendres plutôt que de la carotte crue.']::text[], 'Les pois chiches et le pain pita associent légumineuse et céréale ; le sésame apporte du calcium.', 1, array[]::text[], 'cold', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
