insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-couscous-legumes-pois-chiches-navet' and owner_id is null), 1, 'Faites revenir l’oignon émincé dans 2 cuillères d’huile avec le ras-el-hanout. Ajoutez les carottes et les navets en tronçons, les tomates concassées et 1,5 l d’eau.') on conflict do nothing;
