insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-risotto-petits-pois-parmesan-citron', 'Risotto crémeux aux petits pois, parmesan et citron', 'Un risotto doux et printanier, que les enfants peuvent remuer avec vous.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 10, 30, array['gluten','milk','celery']::text[], array['vegetarian','calcium','family','picky','vegetables']::text[], array['Pour plus de protéines, ajoutez 150 g d’edamame ou de haricots blancs.','Avant 4 ans, écrasez légèrement les petits pois.']::text[], '24 h au réfrigérateur ; réchauffez avec un peu d’eau. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Choisissez un bouillon sans sel ajouté et vérifiez l’étiquette (céleri, gluten).']::text[], 'Le parmesan apporte du calcium et des protéines ; les petits pois, des fibres.', 2, array['spring']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
