insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-nouilles-tofu-sauce-cacahuete-concombre', 'Nouilles tièdes au tofu, sauce douce à la cacahuète et concombre', 'Des nouilles nappées d’une sauce onctueuse à la cacahuète, avec du tofu doré et des crudités.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 36, 120, array['regular']::text[], 4, null, 20, 15, array['gluten','eggs','peanuts','soy']::text[], array['vegetarian','protein','world','vegetables','lunchbox']::text[], array['Allergie à l’arachide : remplacez le beurre de cacahuète par du tahini (sésame) ou un yaourt.','Allergie au soja : remplacez le tofu par des œufs durs.']::text[], '24 h au réfrigérateur ; à servir tiède ou froid.', array['Beurre de cacahuète uniquement en sauce délayée, jamais de cacahuètes entières avant 4 ans.','Carottes râpées finement et nouilles coupées courtes.','Arachide : à proposer seulement si elle a déjà été introduite sans réaction ; une première fois se fait à la maison, en petite quantité, quand on peut surveiller l’enfant. En cas d’allergie connue ou de doute, demandez l’avis du médecin.']::text[], 'Le tofu et le beurre de cacahuète apportent des protéines ; les nouilles, des féculents ; les crudités, des fibres.', 2, array['spring','summer']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
