insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-riz-au-lait-coco-mangue', 'Riz au lait de coco et à la mangue', 'Un dessert crémeux au lait et au lait de coco, sucré par la mangue.', array['child','family']::text[], array['dessert','snack']::text[], array[]::text[], 24, 120, array['regular']::text[], 6, null, 10, 40, array['milk']::text[], array['vegetarian','calcium','world','make_ahead','budget']::text[], array['Sans lait de vache : utilisez uniquement du lait de coco allongé d’eau.','Remplacez la mangue par de l’ananas ou une compote.']::text[], '3 jours au réfrigérateur. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array[]::text[], 'Le lait apporte du calcium ; la mangue sucre le dessert sans sucre ajouté.', 2, array['summer','winter']::text[], 'cold', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
