insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('vg-ratatouille-quinoa-oeufs-durs', 'Ratatouille douce au quinoa et œufs durs', 'Une ratatouille mijotée servie sur du quinoa, avec des œufs durs en quartiers.', array['child','family']::text[], array['lunch','dinner']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 25, 45, array['eggs']::text[], array['vegetarian','protein','vegetables','fiber','batch','freezer']::text[], array['Remplacez les œufs par des pois chiches.','Pour les plus jeunes, écrasez les œufs à la fourchette.']::text[], 'Ratatouille : 3 jours au réfrigérateur ou 3 mois au congélateur.', array['Œufs durs bien cuits.']::text[], 'Le quinoa et les œufs apportent des protéines ; la ratatouille, des légumes variés.', 2, array['summer']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
