insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'vg-ratatouille-quinoa-oeufs-durs' and owner_id is null), 9, 'herbs', 'herbes de Provence', 1, 'cc', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-ratatouille-quinoa-oeufs-durs' and owner_id is null), 1, 'Coupez l’aubergine, les courgettes, le poivron et les tomates en petits cubes ; émincez l’oignon.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-ratatouille-quinoa-oeufs-durs' and owner_id is null), 2, 'Faites revenir l’oignon et le poivron 5 minutes dans l’huile d’olive, puis ajoutez les autres légumes et les herbes de Provence. Laissez mijoter 35 minutes à couvert, jusqu’à ce que tout soit fondant.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-ratatouille-quinoa-oeufs-durs' and owner_id is null), 3, 'Pendant ce temps, faites cuire le quinoa rincé 12 à 15 minutes dans deux fois son volume d’eau.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'vg-ratatouille-quinoa-oeufs-durs' and owner_id is null), 4, 'Faites cuire les œufs 10 minutes à l’eau bouillante (jaune bien pris), écalez-les et coupez-les en quartiers. Servez sur le quinoa et la ratatouille.') on conflict do nothing;
