insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('lg-veloute-butternut-lait-coco', 'Velouté de butternut au lait de coco', 'Un velouté orange tout doux, légèrement sucré par la courge, qui se boit volontiers au bol.', array['child','family']::text[], array['dinner','lunch']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 15, 25, array[]::text[], array['vegetables','batch','freezer','picky','vegetarian']::text[], array['Pour les enfants qui hésitent, servez-le dans une tasse avec une paille large ou avec des mouillettes de pain.','Le gingembre est facultatif : commencez sans, puis ajoutez-le petit à petit.']::text[], '3 jours au réfrigérateur, 3 mois au congélateur en portions.', array['Laissez tiédir avant de servir : un velouté mixé garde longtemps la chaleur.']::text[], 'La butternut apporte des caroténoïdes (pigments orange) et le lait de coco des matières grasses.', 1, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'lg-veloute-butternut-lait-coco' and owner_id is null), 1, 'butternut', 'courge butternut', 800, 'g', '1 petite courge', false) on conflict do nothing;
