insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'lg-veloute-butternut-lait-coco' and owner_id is null), 1, 'Épluchez la butternut, retirez les graines et coupez la chair en cubes. Pelez et émincez l’oignon.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'lg-veloute-butternut-lait-coco' and owner_id is null), 2, 'Faites revenir l’oignon 3 minutes dans l’huile d’olive, sans le colorer.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'lg-veloute-butternut-lait-coco' and owner_id is null), 3, 'Ajoutez les cubes de butternut, couvrez d’eau à hauteur et laissez cuire 20 minutes à frémissement, jusqu’à ce que la courge s’écrase à la fourchette.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'lg-veloute-butternut-lait-coco' and owner_id is null), 4, 'Mixez finement en ajoutant le lait de coco, la pincée de gingembre si vous l’utilisez et le sel. Rallongez avec un peu d’eau chaude si le velouté est trop épais.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'lg-veloute-butternut-lait-coco' and owner_id is null), 5, 'Vérifiez la température avant de servir aux enfants.') on conflict do nothing;
