insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'lg-chips-betterave-four' and owner_id is null), 2, 'Mélangez délicatement avec l’huile d’olive et étalez sans superposer sur deux plaques.') on conflict do nothing;
