insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gd-brochettes-fruits-dip-yaourt-citron', 'Brochettes de fruits et dip au yaourt citronné', 'Des fruits de saison enfilés sur des piques à bout rond, à tremper dans un yaourt parfumé au citron.', array['child','family']::text[], array['snack']::text[], array[]::text[], 36, 120, array['regular']::text[], 4, null, 15, 0, array['milk']::text[], array['finger','quick','calcium','vegetarian']::text[], array['Sans piques : servez les fruits dans un bol et le dip à part, à piquer avec une fourchette.','Selon la saison : pêche, poire bien mûre, ananas ou mangue.']::text[], 'Les fruits coupés se gardent 4 h au réfrigérateur dans une boîte fermée ; la banane noircit vite, ajoutez-la au dernier moment.', array['Piques à bout rond seulement, et sous la surveillance d’un adulte ; retirez la pique pour les enfants qui marchent ou courent en mangeant.','Avant 4 ans : surveillez l’enfant pendant le goûter, assis, et proposez des morceaux adaptés à son âge.']::text[], 'Plusieurs fruits frais et un laitage, sans sucre ajouté.', 2, array['spring','summer']::text[], 'cold', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
