insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gd-yaourts-maison-vanille' and owner_id is null), 2, 'Fouettez le yaourt nature dans un bol, puis ajoutez le lait tiède petit à petit.') on conflict do nothing;
