insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gd-riz-au-lait-coco-mangue', 'Riz au lait de coco et mangue', 'Un riz au lait crémeux au lait de coco, servi avec des dés de mangue.', array['child','family']::text[], array['dessert','snack']::text[], array[]::text[], 24, 120, array['regular']::text[], 6, null, 10, 35, array['milk']::text[], array['calcium','world','make_ahead','vegetarian']::text[], array['Remplacez la mangue par de l’ananas ou une banane.','Tout au lait de vache si vous n’avez pas de lait de coco.']::text[], '3 jours au réfrigérateur, sans la mangue. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array[]::text[], 'Un dessert lacté à base de céréale avec environ 7 g de sucre ajouté par portion.', 1, array[]::text[], 'cold', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
