insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gd-mini-cakes-mais-emmental-ciboulette' and owner_id is null), 4, 'Répartissez dans 12 moules à mini-cakes ou à muffins et enfournez 20 à 22 minutes. Vérifiez la cuisson en piquant le centre avec la pointe d’un couteau : elle doit ressortir sèche (œufs cuits à cœur).') on conflict do nothing;
