insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gd-pain-perdu-pommes-cannelle', 'Pain perdu aux pommes poêlées et à la cannelle', 'Un pain perdu sans sucre dans l’appareil, garni de pommes fondantes.', array['child','family']::text[], array['snack','dessert']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 10, 15, array['gluten','eggs','milk']::text[], array['budget','quick','family','vegetarian']::text[], array['Avec des poires ou des bananes poêlées.','Utilisez du pain complet rassis pour éviter le gaspillage.']::text[], 'À déguster tiède ; les pommes poêlées se gardent 2 jours au frais.', array['L’œuf doit être cuit, sans partie coulante.']::text[], 'Un goûter à base de pain et de fruit, sans sucre ajouté.', 1, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
