insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gd-pain-perdu-pommes-cannelle' and owner_id is null), 5, 'cinnamon', 'cannelle', 1, 'cc', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gd-pain-perdu-pommes-cannelle' and owner_id is null), 6, 'butter', 'beurre', 20, 'g', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gd-pain-perdu-pommes-cannelle' and owner_id is null), 1, 'Épluchez les pommes, coupez-les en fines lamelles et faites-les fondre 8 minutes à la poêle avec la moitié du beurre et la cannelle, jusqu’à ce qu’elles soient bien tendres.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gd-pain-perdu-pommes-cannelle' and owner_id is null), 2, 'Battez les œufs avec le lait dans une assiette creuse.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gd-pain-perdu-pommes-cannelle' and owner_id is null), 3, 'Trempez les tranches de pain de mie des deux côtés dans ce mélange.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gd-pain-perdu-pommes-cannelle' and owner_id is null), 4, 'Faites-les dorer 3 minutes de chaque côté dans le reste du beurre, jusqu’à ce que l’œuf soit bien cuit et qu’il n’y ait plus de partie liquide.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gd-pain-perdu-pommes-cannelle' and owner_id is null), 5, 'Coupez en mouillettes et servez tiède, garni des pommes.') on conflict do nothing;
