insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('gd-crepes-sarrasin-compote', 'Crêpes au sarrasin garnies de compote', 'Des crêpes au goût de noisette, garnies de compote sans sucre ajouté.', array['child','family']::text[], array['snack','dessert']::text[], array[]::text[], 24, 120, array['regular']::text[], 4, null, 10, 20, array['eggs','milk']::text[], array['budget','family','vegetarian']::text[], array['Version salée : garnissez d’emmental râpé et de blanc de dinde.','Pour l’allergie au gluten, choisissez une farine de sarrasin garantie sans traces de blé.']::text[], 'Les crêpes se gardent 2 jours au réfrigérateur, filmées ; réchauffez-les à la poêle.', array[]::text[], 'Une céréale complète, du lait et un fruit, sans sucre ajouté.', 1, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gd-crepes-sarrasin-compote' and owner_id is null), 1, 'buckwheat_flour', 'farine de sarrasin (traces de blé possibles : vérifiez l’étiquette)', 100, 'g', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gd-crepes-sarrasin-compote' and owner_id is null), 2, 'egg', 'œuf', 1, 'u', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gd-crepes-sarrasin-compote' and owner_id is null), 3, 'milk', 'lait demi-écrémé (pasteurisé ou UHT)', 250, 'ml', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gd-crepes-sarrasin-compote' and owner_id is null), 4, 'rapeseed_oil', 'huile de colza', 1, 'cs', null, false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'gd-crepes-sarrasin-compote' and owner_id is null), 5, 'compote_unsweetened', 'compote de pommes sans sucre ajouté', 200, 'g', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gd-crepes-sarrasin-compote' and owner_id is null), 1, 'Mélangez la farine de sarrasin et l’œuf, puis versez le lait petit à petit en fouettant pour obtenir une pâte lisse ; laissez reposer 30 minutes si possible.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gd-crepes-sarrasin-compote' and owner_id is null), 2, 'Faites chauffer une poêle légèrement huilée et versez une petite louche de pâte en l’étalant finement.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gd-crepes-sarrasin-compote' and owner_id is null), 3, 'Faites cuire environ 1 minute de chaque côté, jusqu’à ce que la crêpe soit bien sèche et dorée ; continuez avec le reste de la pâte.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'gd-crepes-sarrasin-compote' and owner_id is null), 4, 'Garnissez chaque crêpe de compote, pliez-la en quatre et coupez en triangles pour les plus jeunes.') on conflict do nothing;
