insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('em-wrap-poulet-avocat-mais', 'Wraps au poulet, avocat et maïs pour la boîte à repas', 'Des galettes roulées garnies de poulet tendre, d’avocat écrasé et de maïs, faciles à manger avec les mains.', array['child','family']::text[], array['lunch']::text[], array[]::text[], 36, 120, array['regular']::text[], 4, null, 15, 10, array['gluten','milk']::text[], array['lunchbox','quick','protein']::text[], array['Version végétarienne : remplacez le poulet par des pois chiches écrasés.','Avant 4 ans, coupez le wrap en petits tronçons faciles à tenir.']::text[], '24 h au réfrigérateur, dans une boîte isotherme avec un pain de glace pour l’école.', array['Gardez au frais jusqu’au repas (chaîne du froid).','Avant 4 ans : écrasez les grains de maïs (risque d’étouffement).']::text[], 'Associe un féculent, une volaille et des légumes dans une même préparation à emporter.', 2, array[]::text[], 'cold', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
