insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'em-wrap-poulet-avocat-mais' and owner_id is null), 7, 'lemon', 'citron', 1, 'cc', 'jus', false) on conflict do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'em-wrap-poulet-avocat-mais' and owner_id is null), 8, 'olive_oil', 'huile d''olive', 1, 'cs', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-wrap-poulet-avocat-mais' and owner_id is null), 1, 'Coupez le poulet en fines lamelles et faites-le cuire 8 à 10 minutes à la poêle dans l’huile d’olive, jusqu’à ce qu’il soit bien cuit à cœur (plus aucune trace rosée). Laissez refroidir.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-wrap-poulet-avocat-mais' and owner_id is null), 2, 'Écrasez l’avocat à la fourchette avec le yaourt et le jus de citron pour obtenir une crème lisse.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-wrap-poulet-avocat-mais' and owner_id is null), 3, 'Lavez et séchez les feuilles de salade, puis émincez-les finement.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-wrap-poulet-avocat-mais' and owner_id is null), 4, 'Étalez la crème d’avocat sur les galettes de blé, répartissez le poulet, le maïs égoutté et la salade.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-wrap-poulet-avocat-mais' and owner_id is null), 5, 'Roulez bien serré, coupez chaque wrap en deux et enveloppez-le dans du papier cuisson pour la boîte.') on conflict do nothing;
