insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('em-pizza-blanche-ricotta-epinards', 'Pizza blanche à la ricotta, épinards et mozzarella', 'Une pizza sans sauce tomate, toute douce, avec une base crémeuse de ricotta et des épinards fondants.', array['child','family']::text[], array['dinner']::text[], array[]::text[], 36, 120, array['regular']::text[], 4, null, 15, 15, array['gluten','milk']::text[], array['vegetarian','calcium','vegetables','world']::text[], array['On peut ajouter quelques dés de jambon cuit ou de poulet cuit.','Laissez tiédir : le fromage fondu est très chaud à la sortie du four.']::text[], '2 jours au réfrigérateur ; les parts froides se glissent dans la boîte à repas.', array['Attention au fromage fondu brûlant : laissez tiédir avant de servir.']::text[], 'Une base de pâte à pizza, des produits laitiers et un légume vert.', 2, array[]::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
