insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('em-sandwich-poulet-curry-pomme', 'Sandwich complet au poulet, sauce douce au curry et pomme', 'Un sandwich frais où la pomme râpée apporte du croquant et une note sucrée.', array['child','family']::text[], array['lunch']::text[], array[]::text[], 36, 120, array['regular']::text[], 4, null, 15, 10, array['gluten','milk','celery','mustard']::text[], array['lunchbox','protein','fiber']::text[], array['Version végétarienne : remplacez le poulet par des œufs durs émiettés.','Avant 4 ans, la pomme crue est toujours râpée.']::text[], '24 h au réfrigérateur dans une boîte hermétique.', array['Pomme crue râpée avant 4 ans.','Gardez au frais jusqu’au repas.']::text[], 'Pain complet, volaille et fruit cru réunis dans un sandwich.', 2, array[]::text[], 'cold', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
