insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('em-houmous-batonnets-legumes', 'Houmous maison et bâtonnets de légumes à tremper', 'Une crème de pois chiches au sésame, servie avec des légumes croquants pour le goûter ou le pique-nique.', array['child','family']::text[], array['snack','lunch']::text[], array[]::text[], 36, 120, array['regular']::text[], 4, null, 15, 0, array['sesame']::text[], array['world','vegetarian','lunchbox','fiber','finger','make_ahead']::text[], array['Allergie au sésame : supprimez la purée de sésame et ajoutez un peu plus d’huile d’olive.','Le houmous peut aussi se tartiner dans un wrap.']::text[], '3 jours au réfrigérateur dans un bocal fermé.', array['Carotte crue : râpée finement avant 4 ans.','Gardez au frais jusqu’au repas.']::text[], 'Les pois chiches sont une légumineuse ; associés aux légumes crus, ils forment un en-cas consistant.', 1, array[]::text[], 'cold', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
