insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'em-houmous-batonnets-legumes' and owner_id is null), 8, 'cucumber', 'concombre', 0.5, 'u', null, false) on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-houmous-batonnets-legumes' and owner_id is null), 1, 'Rincez les pois chiches et mixez-les avec la purée de sésame, le jus de citron, l’ail, l’huile d’olive, le cumin et 3 à 4 cuillères d’eau froide, jusqu’à obtenir une crème bien lisse.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-houmous-batonnets-legumes' and owner_id is null), 2, 'Épluchez les carottes et lavez le concombre.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-houmous-batonnets-legumes' and owner_id is null), 3, 'Après 4 ans, coupez carottes et concombre en bâtonnets ; avant 4 ans, servez le concombre en bâtonnets épais et les carottes râpées finement.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-houmous-batonnets-legumes' and owner_id is null), 4, 'Servez le houmous dans un petit pot avec les légumes à côté.') on conflict do nothing;
