insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('em-moujaddara-riz-lentilles-oignons', 'Moujaddara : riz et lentilles aux oignons fondants', 'Le plat libanais du quotidien, très économique : riz et lentilles vertes cuits ensemble, surmontés d’oignons dorés.', array['child','family']::text[], array['dinner','lunch']::text[], array[]::text[], 36, 120, array['regular']::text[], 4, null, 15, 40, array['milk']::text[], array['world','vegetarian','budget','iron','fiber','make_ahead']::text[], array['Pour les enfants qui n’aiment pas les oignons, servez-les à part.','Se mange aussi tiède ou froide dans la boîte à repas.']::text[], '3 jours au réfrigérateur. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Riz cuit : refroidir rapidement et garder au frais.']::text[], 'Lentilles et riz se complètent dans un plat végétarien économique.', 1, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
insert into public.recipe_ingredients (recipe_id, position, ingredient_key, label, qty, unit, note, optional) values ((select id from public.recipes where slug = 'em-moujaddara-riz-lentilles-oignons' and owner_id is null), 1, 'green_lentils', 'lentilles vertes', 150, 'g', null, false) on conflict do nothing;
