insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-moujaddara-riz-lentilles-oignons' and owner_id is null), 1, 'Rincez les lentilles et faites-les cuire 15 minutes dans 600 ml d’eau.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-moujaddara-riz-lentilles-oignons' and owner_id is null), 2, 'Pendant ce temps, émincez finement les oignons et faites-les fondre 20 minutes à feu doux dans l’huile d’olive, jusqu’à ce qu’ils soient bien dorés et tendres.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-moujaddara-riz-lentilles-oignons' and owner_id is null), 3, 'Ajoutez le riz rincé, le cumin et la moitié des oignons aux lentilles ; complétez avec 200 ml d’eau si besoin, couvrez et laissez cuire 18 à 20 minutes jusqu’à absorption.') on conflict do nothing;
