insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-couscous-poulet-legumes-ras-el-hanout' and owner_id is null), 1, 'Dans une grande cocotte, faites dorer les cuisses de poulet 5 minutes dans l’huile d’olive avec l’oignon émincé.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-couscous-poulet-legumes-ras-el-hanout' and owner_id is null), 2, 'Ajoutez le ras-el-hanout, les tomates concassées, les carottes et les navets coupés en gros tronçons ; couvrez d’eau et laissez mijoter 20 minutes.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-couscous-poulet-legumes-ras-el-hanout' and owner_id is null), 3, 'Ajoutez la courge coupée en cubes, les courgettes et les pois chiches ; poursuivez 20 minutes, jusqu’à ce que le poulet soit bien cuit à cœur et les légumes tendres.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-couscous-poulet-legumes-ras-el-hanout' and owner_id is null), 4, 'Pendant ce temps, versez la semoule dans un saladier, couvrez du même volume d’eau bouillante, laissez gonfler 5 minutes et égrainez à la fourchette.') on conflict do nothing;
insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-couscous-poulet-legumes-ras-el-hanout' and owner_id is null), 5, 'Retirez la peau et les os du poulet avant de servir aux enfants, avec les légumes et un peu de bouillon.') on conflict do nothing;
