insert into public.recipe_steps (recipe_id, position, body) values ((select id from public.recipes where slug = 'em-tajine-kefta-boeuf-tomate' and owner_id is null), 1, 'Mélangez le bœuf haché avec la moitié du persil haché, le cumin et la moitié du paprika ; formez une vingtaine de petites boulettes.') on conflict do nothing;
