insert into public.recipes (slug, title, summary, audiences, meals, stages, min_months, max_months, textures, servings, serving_label, prep_min, cook_min, allergens, tags, adaptations, storage, precautions, nutrition, budget, seasons, temperature, family_adaptations, verified_on, status) values ('em-chili-con-carne-doux-carottes', 'Chili con carne doux aux carottes et haricots rouges', 'Un chili sans piment où les carottes râpées adoucissent la sauce, servi avec du riz.', array['child','family']::text[], array['dinner','lunch']::text[], array[]::text[], 36, 120, array['regular']::text[], 6, null, 15, 35, array[]::text[], array['world','budget','batch','freezer','iron','make_ahead','family']::text[], array['Servez avec un peu de fromage râpé ou de yaourt nature.','Avant 4 ans, écrasez un peu les haricots dans l’assiette ; le piment se rajoute dans l’assiette des adultes.']::text[], '3 jours au réfrigérateur ; se congèle 3 mois. Riz cuit : refroidir en moins de 2 h, garder 24 h au réfrigérateur (48 h au plus), réchauffer une seule fois, bien chaud ; congeler la garniture sans le riz.', array['Viande hachée cuite à cœur, sans partie rosée.','Avant 4 ans : écrasez les grains de maïs (risque d’étouffement).']::text[], 'Viande, légumineuses et céréale réunies dans un plat mijoté.', 1, array['autumn','winter']::text[], 'hot', '{}'::jsonb, '2026-10-20', 'ai_draft') on conflict (slug) do nothing;
